    {
      "path": "package.json",
      "content": "{\n  \"name\": \"@yolk_vat-y/dsh-project-memory\",\n  \"version\": \"0.6.5\",\n  \"description\": \"Persistent project memory for dsh agents: index docs (PDF/Markdown/text) and code symbols into a searchable per-workspace store, recall them with cited sources, and keep experience entries (problems -> solutions) searchable on demand.\",\n  \"author\": \"00080000 <3388065969@qq.com>\",\n  \"type\": \"module\",\n  \"main\": \"src/index.js\",\n  \"files\": [\n    \"src\",\n    \"skills\",\n    \"client\",\n    \"scripts\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"README.zh-CN.md\",\n    \"CHANGELOG.md\"\n  ],\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"https://github.com/00080000/dsh-project-memory.git\"\n  },\n  \"scripts\": {\n    \"test\": \"node test/run-test.mjs && node test/taskbridge.test.mjs && node test/insight-store.test.mjs && node test/reflection-pipeline.test.mjs && node test/auto-inject.test.mjs && node test/insight-actions.test.mjs && node test/insight-paging.test.mjs && node test/config-schema.test.mjs && node test/host-contract.test.mjs && node test/session-dir.test.mjs && node test/llm-route.test.mjs && node test/doc-index.test.mjs && node test/chunker.test.mjs && node test/client-hints.test.mjs && node test/client-paging.test.mjs && node test/client-task-sync.test.mjs && node test/recall.test.mjs && node test/recall-vector-fusion.test.mjs && node test/vector-index.test.mjs && node test/readiness.test.mjs && node test/insight-derive.test.mjs && node test/readiness-eval.test.mjs && node test/ops.test.mjs && node test/injection-audit.test.mjs && node test/signal-source.test.mjs && node test/skill.test.mjs && node test/injection-budget.test.mjs && node test/injection-scenarios.test.mjs && node test/bugfix-0.5.7.test.mjs && node test/client-icons.test.mjs && node test/client-slash.test.mjs && node test/client-toolview.test.mjs && node test/workflow-command.test.mjs && node test/client-session-id.test.mjs && node test/client-degraded.test.mjs && node test/watch-idle.test.mjs && node test/citation-paths.test.mjs && node test/task-view.test.mjs && node test/root-guards.test.mjs && node test/root-policy.test.mjs && node test/gitignore-index.test.mjs && node test/store-gitignore.test.mjs && node test/atomic-write.test.mjs && node test/store-cache.test.mjs && node test/store-concurrent.test.mjs && node test/store-lock.test.mjs && node test/tool-schema-size.test.mjs && node test/enhancer.test.mjs\",\n    \"eval:injection\": \"node test/injection-scenarios.test.mjs\",\n    \"typecheck\": \"tsc -p tsconfig.json && tsc -p tsconfig.client.json\",\n    \"selfcheck:triggers\": \"node test/injection-scenarios.test.mjs --selfcheck\",\n    \"bench\": \"node scripts/bench.mjs\",\n    \"bench:synthetic\": \"node scripts/bench-synthetic.mjs\",\n    \"bench:peak\": \"node --expose-gc scripts/file-peak.mjs\",\n    \"bench:store\": \"node scripts/bench-store.mjs\",\n    \"schema:size\": \"node scripts/tool-schema-size.mjs\",\n    \"build:client\": \"tsdown\",\n    \"bench:edits\": \"node scripts/bench-edits.mjs\"\n  },\n  \"keywords\": [\n    \"dsh\",\n    \"dsh-plugin\",\n    \"deepseek-harness\",\n    \"memory\",\n    \"project-memory\",\n    \"rag\",\n    \"codebase\",\n    \"cordis\"\n  ],\n  \"license\": \"MIT\",\n  \"publishConfig\": {\n    \"access\": \"public\",\n    \"registry\": \"https://registry.npmjs.org\"\n  },\n  \"engines\": {\n    \"node\": \">=18\"\n  },\n  \"dependencies\": {\n    \"pdfjs-dist\": \"^4.10.38\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.4\",\n    \"@deepseek-ai/dsh-client-locale\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-store\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-llm\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-tools\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/schemastery\": \"^3.18.2\",\n    \"@tsdown/css\": \"0.22.14\",\n    \"@types/react\": \"^18.3.31\",\n    \"@types/react-dom\": \"^18.3.7\",\n    \"lightningcss\": \"^1.33.0\",\n    \"tsdown\": \"^0.22.14\",\n    \"typescript\": \"^5.6.3\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\",\n    \"@deepseek-ai/dsh-llm\": \">=0.0.1-rc.1 <0.1.0 || >=0.1.0-rc.1 <0.2.0-0 || >=0.1.1-rc.1 <0.2.0-0 || >=0.2.0-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-tools\": \">=0.0.1-rc.1 <0.1.0 || >=0.1.0-rc.1 <0.2.0-0 || >=0.1.1-rc.1 <0.2.0-0 || >=0.2.0-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/schemastery\": \"^3.18.1\",\n    \"typescript\": \"^5.0.0 || ^6.0.0\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/cordis\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-tools\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/schemastery\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-llm\": {\n      \"optional\": true\n    },\n    \"typescript\": {\n      \"optional\": true\n    }\n  },\n  \"dsh\": {\n    \"engines\": {\n      \"dsh\": \">=0.0.1-rc.1 <0.1.0 || >=0.1.0-rc.1 <0.3.0-0\"\n    },\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-locale\"\n      ],\n      \"platform\": \"web\"\n    }\n  },\n  \"exports\": {\n    \".\": \"./src/index.js\",\n    \"./client\": \"./client/client.js\",\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\"\n  },\n  \"optionalDependencies\": {\n    \"leanvec\": \"^0.1.0\"\n  }\n}\n"
