    {
      "path": "src/tools/query-memory.js",
      "content": "import { defineTool } from '@deepseek-ai/dsh-tools'\nimport path from 'node:path'\nimport { assertIndexRoot, memoryDirName, memoryRootFor, nestedStoreRoots, resolveSafeIndexRoot } from '../util/fs.js'\nimport { ProjectMemoryStore, storeOverview } from '../store.js'\nimport { expandQuery } from '../llm.js'\nimport { resolveRoute } from '../llm-route.js'\nimport { GlobalStore, cfgInsight, defaultGlobalFile, recordHit } from '../insight-store.js'\nimport { recallItems } from '../recall.js'\nimport { cfgEngine } from '../auto-inject.js'\nimport { createVectorRerank, vectorItemsFrom } from '../vector-index.js'\nimport { resolveLinkedSymbols } from '../link.js'\nimport { truncate } from '../util/text.js'\nimport { stepContent, stepStatus } from '../util/task-view.js'\nfunction toAbs(root, rel) {\n  return path.isAbsolute(rel) ? rel : path.join(root, rel)\n}\n\n/**\n * 本根未命中记忆层时，把\"这里有哪几个独立子索引\"告诉模型。\n *\n * 父根不再重复保存子项目的内容（`walkDir()` 跳过自带 store 的嵌套根），所以\"在父根下问子项目的\n * 事\"必然查不到；换 `root=` 再问一次是唯一正确的下一步。只在未命中时算，不在热路径上。\n */\nfunction nestedIndexNote(root, config) {\n  const nested = nestedStoreRoots(root, memoryDirName(config))\n  if (!nested.length) return ''\n  return (\n    `\\n\\nNote: this root keeps no copy of ${nested.length} nested project(s) — each has its own index. ` +\n    'Re-run query_memory with `root: <path>` for the one you want:\\n' +\n    nested.map((p) => `- ${p}`).join('\\n')\n  )\n}\n\n/**\n * 一段结果里最佳条目的跨层排序分（`rel × 层先验`，与 `recallItems` 返回的 `flat.hint`\n * 同一口径）。只用于决定段落先后，不参与打分，也不改变任何条目自身的 score。\n */\nfunction bestHint(hits) {\n  let best = 0\n  for (const h of hits || []) best = Math.max(best, (h.rel || 0) * (h.prior || 1))\n  return best\n}\n\n/** 被覆盖字段的上一版：只显示一行，方便模型判断是否写回；空槽不占位。 */\nfunction previousLine(item) {\n  if (!item || !item.prev || typeof item.prev !== 'object' || Array.isArray(item.prev)) return ''\n  const parts = []\n  for (const [key, value] of Object.entries(item.prev)) {\n    if (value === undefined || value === null || value === '') continue\n    const raw = typeof value === 'string' ? value : JSON.stringify(value)\n    const text = raw ? raw.replace(/\\s+/g, ' ').trim() : ''\n    if (!text) continue\n    parts.push(`${key}=${text}`)\n  }\n  return parts.length ? parts.join('; ').slice(0, 300) : ''\n}\n\nexport function queryMemoryTool(ctx, config) {\n  return defineTool({\n    name: 'query_memory',\n    description:\n      'Search project memory: docs, symbols, experience and insights. Returns cited sources or insight ids. '\n      + 'Use before grepping for orientation, a spec constraint, or a past decision.',\n    parameters: {\n      query: {\n        type: 'string',\n        required: true,\n        description: 'What to look for',\n      },\n      root: {\n        type: 'string',\n        description: '项目根（默认当前工作目录）',\n      },\n      type: {\n        type: 'string',\n        enum: ['all', 'doc', 'symbol', 'experience', 'insight', 'task'],\n        description: 'all|doc|symbol|experience|insight|task；默认 all',\n      },\n      limit: {\n        type: 'number',\n        description: '最多返回条数，默认 8',\n      },\n    },\n    output: {\n      schema: { type: 'string' },\n      render: (_args, value) => [{ type: 'text', text: value }],\n    },\n    async execute(args, exec) {\n      const root = resolveSafeIndexRoot(exec, args.root, config)\n      // 读路径也要验根存在。这条不是洁癖：可选的向量层（leanvec）在空 store 上会建\n      // `<root>/.dsh-project-memory/vectors.json`，于是传错一个 root（拼写错误/旧路径）就能\n      // 在任意可写位置造出目录和空 store，而回报是\"No memory matches\"——看起来像\"这个项目\n      // 没有记忆\"，用户不会意识到自己查错了地方。与 index_repo/watch_repo 同一道护栏。\n      assertIndexRoot(root, args.root || root)\n      // 空查询不是\"全部\"：recallItems 会过滤空串，rankEntriesStreaming 随即返回\n      // entries.slice(0, limit)（任意条目、分数 0），task 分支的 includes('') 更是命中所有任务。\n      if (!String(args.query ?? '').trim()) {\n        return 'query must not be empty. Use memory_stats to see what the store contains.'\n      }\n      const store = new ProjectMemoryStore(memoryRootFor(root, config.memoryDir)).load()\n      const type = args.type || 'all'\n      const limit = Math.max(1, Math.min(Number(args.limit) || 8, 20))\n\n      const queries = config.llmQueryExpansion\n        ? await expandQuery(ctx.llm, args.query, config.expansionCount, { route: resolveRoute(exec, config) })\n        : [args.query]\n\n      // 会话绑定决定 task 级 insight 的可见性；global 级始终可见。\n      const sessionId = exec?.agent?.session?.id\n      const boundTaskId = sessionId && typeof store.getBoundTaskId === 'function' ? store.getBoundTaskId(sessionId) : null\n      const globalStore = new GlobalStore(cfgInsight(config).globalFile || defaultGlobalFile()).load()\n      const wantMemory = type === 'all' || type === 'doc' || type === 'symbol'\n      /** 本根记忆层（doc/symbol）的命中数：0 且存在子索引时，末尾要指路。 */\n      let memHitCount = 0\n      const wantInsight = type === 'all' || type === 'insight'\n      // 可选向量层：**没装/没配就是 null**，此时 recallItems 拿到 rerank:null 与纯词法路径逐字段一致。\n      // 只影响 experience/insight 两层的排序（doc/symbol 与返回条数都不变）。\n      const cfg = cfgEngine(config)\n      const rerank = await createVectorRerank({\n        storeDir: memoryRootFor(root, config.memoryDir),\n        items: vectorItemsFrom(store, globalStore),\n        vectorDir: cfg.vectorDir,\n        alpha: cfg.vectorAlpha,\n      })\n      // 一次 recall 覆盖全部层：doc/symbol/experience/insight 共用同一个检索核心（src/recall.js）。\n      const recalled = recallItems({\n        store,\n        globalStore,\n        queries,\n        boundTaskId,\n        limit,\n        rerank,\n        layers: [\n          ...(wantMemory ? (type === 'symbol' ? ['symbol'] : type === 'doc' ? ['doc'] : ['doc', 'symbol']) : []),\n          ...(wantInsight ? ['insight'] : []),\n          ...(type === 'all' || type === 'experience' ? ['experience'] : []),\n        ],\n      })\n\n      const lines = []\n      // 结果段先按相关性排序，最后再拼进 lines（见下方 sections.sort）。\n      const sections = []\n      // 使用记账：检索命中也是\"被用到\"（活跃度/衰减用得上它，见 recordHit）。查询是热路径\n      // （p50 2.6ms），这里只改内存 + 标脏，**不**强制落盘——注入路径会立即落盘，这条路\n      // 靠下一次自然 save 带上。记账失败绝不影响查询结果。\n      // 经验层同源（kind:'experience' 的 insight），所以两桶都要记：`insightId` 是 insight\n      // 适配器带的键，经验桶给的是原始条目，用 `id` 兜底。\n      for (const layer of ['insight', 'experience']) {\n        if (layer === 'insight' && !wantInsight) continue\n        if (layer === 'experience' && !(type === 'all' || type === 'experience')) continue\n        try {\n          const bucket = recalled.layers.find((l) => l.layer === layer)\n          recordHit({ store, globalStore, ids: (bucket?.hits || []).map((h) => h.item?.insightId || h.item?.id) })\n        } catch {\n          /* ignore：记账是旁路 */\n        }\n      }\n      if (wantMemory) {\n        // doc/symbol 的原始 BM25 分不可直接比：符号正文短，同等相关时分会更高/更低，\n        // 用原始分排序会让一层把另一层整体挤掉。先按**层内相对分 rel** 排序，并在\n        // limit≥2 时各保留一条，剩余名额再按 rel 填。\n        const docHits = recalled.layers.find((l) => l.layer === 'doc')?.hits || []\n        const symbolHits = recalled.layers.find((l) => l.layer === 'symbol')?.hits || []\n        const byRel = (a, b) => (b.rel || 0) - (a.rel || 0) || (b.weightedScore || 0) - (a.weightedScore || 0)\n        const merged = [...docHits, ...symbolHits].sort(byRel)\n        const picked = []\n        const seenHits = new Set()\n        const take = (h) => {\n          if (!h || picked.length >= limit) return\n          const key = h.item?.id || `${h.item?.type}:${h.item?.title}`\n          if (seenHits.has(key)) return\n          seenHits.add(key)\n          picked.push(h)\n        }\n        if (limit >= 2) {\n          for (const h of [docHits[0], symbolHits[0]].filter(Boolean).sort(byRel)) take(h)\n        }\n        for (const h of merged) take(h)\n        const memHits = picked\n        memHitCount = memHits.length\n        if (memHits.length) {\n          const block = [`## Memory (${type === 'all' ? 'docs + symbols' : type})`]\n          for (const { item: e, rel } of memHits) {\n            const absSource = e.sourceLine ? `${toAbs(root, e.sourcePath)}:${e.sourceLine}` : toAbs(root, e.sourcePath)\n            const score = Math.round((rel || 0) * 100)\n            // 符号没有 summary：它的正文就是一行声明。缺正文时退到标题，绝不输出 `- undefined`。\n            const body = e.type === 'symbol' ? (e.text || e.title) : e.summary\n            const summaryLine = body ? `\\n- ${body}` : ''\n            // 条目状态占位（可证伪状态机落地前恒为 exact）。\n            // 先立字段，后续状态机到位时只改值、不改输出契约。\n            block.push(`### ${e.title} (score: ${score})\\n- source: ${absSource}\\n- status: ${e.status || 'exact'}${summaryLine}`)\n            if (e.type === 'doc') {\n              // 读取期解算：链接不落盘，按当前符号表排序取前 5（见 src/link.js）\n              const refs = resolveLinkedSymbols(store, e, 5).map(\n                (s) => `${s.title} @ ${toAbs(root, s.sourcePath)}:${s.sourceLine}`,\n              )\n              if (refs.length) block.push(`- references: ${refs.join('; ')}`)\n            }\n          }\n          sections.push({ block, best: bestHint(memHits) })\n        }\n      }\n      if (wantInsight) {\n        const bucket = recalled.layers.find((l) => l.layer === 'insight')\n        if (bucket && bucket.hits.length) {\n          const block = ['## Insights (lessons / decisions / procedures)']\n          for (const { item: e, rel } of bucket.hits) {\n            const scope = e.scope ? `, scope: ${e.scope}` : ''\n            const files = e.files && e.files.length ? `\\n- files: ${e.files.map((f) => toAbs(root, f)).join(', ')}` : ''\n            const conf = typeof e.confidence === 'number' ? `\\n- confidence: ${e.confidence}` : ''\n            const previous = previousLine(e)\n            block.push(\n              `### ${e.title} (score: ${Math.round(rel * 100)}, kind: ${e.kind}${scope}, id: ${e.insightId})\\n- ${e.summary}${files}${conf}${previous ? `\\n- previous: ${previous}` : ''}`,\n            )\n          }\n          sections.push({ block, best: bestHint(bucket.hits) })\n        }\n      }\n      if (type === 'all' || type === 'experience') {\n        const expBucket = recalled.layers.find((l) => l.layer === 'experience')\n        if (expBucket && expBucket.hits.length) {\n          const block = ['## Experience (past problems -> solutions)']\n          for (const { item: e, rel } of expBucket.hits) {\n            // 统一存储后经验条目就是 insight：导入时 source_file 落在 files[0]，新写的也走同一处。\n            const src = e.sourceFile || (Array.isArray(e.files) ? e.files[0] : '')\n            const source = src ? ` (source: ${toAbs(root, src)})` : ''\n            // `problem`/`solution` 只是 v0.4 的字段形状：`save_lesson` 写 kind:'experience'\n            // 时没有这两个参数（正文在 fix/choice/body 里），直接用会渲染出 `undefined`。\n            const problem = e.problem || e.title || '(untitled)'\n            const solution = e.solution || e.fix || e.choice || e.body || '(no text)'\n            block.push(\n              `### Problem: ${problem} (score: ${Math.round(rel * 100)}, id: ${e.id})\\n- solution: ${solution}${source}\\n- updated: ${e.updatedAt}`,\n            )\n          }\n          sections.push({ block, best: bestHint(expBucket.hits) })\n        }\n      }\n\n      // 段落顺序按相关性，而不是写死的 docs 优先：检索已经给出跨层 hint（rel × 层先验），\n      // 排版照它来。否则查一条明确的记忆时，无关的长文档会排在最前、正确答案埋在几千字符\n      // 之后——模型很可能根本没读到。sort 稳定，同分保持 memory → insight → experience。\n      sections.sort((a, b) => b.best - a.best)\n      for (const s of sections) for (const line of s.block) lines.push(line)\n\n      // TaskBridge: type:'task' 专门查任务记录；type:'all' 尾部附一行任务计数提示\n      const tasks = store.tasks || []\n      if (type === 'task') {\n        const q = (queries[0] || '').toLowerCase()\n        const matched = tasks\n          .filter((t) => !t.archived && (t.title.toLowerCase().includes(q) || (t.steps || []).some((s) => stepContent(s).toLowerCase().includes(q)) || (t.files || []).some((f) => f.toLowerCase().includes(q))))\n          .slice(0, limit)\n        if (!matched.length) {\n          return `任务记录: 0 套匹配 \"${args.query}\"（list_tasks 查看全部，select_task 续做）`\n        }\n        for (const t of matched) {\n          const done = (t.steps || []).filter((s) => stepStatus(s) === 'completed').length\n          const total = (t.steps || []).length\n          const stepsText = (t.steps || []).length\n            ? (t.steps || []).map((s) => `- [${stepStatus(s) === 'completed' ? 'x' : stepStatus(s) === 'in_progress' ? '*' : ' '}] ${stepContent(s)}`).join('\\n')\n            : '（无步骤）'\n          const files = (t.files || []).slice(0, 8).join(', ')\n          lines.push(`### ${t.title} (${done}/${total} 完成)\\n${stepsText}\\n- 文件: ${files || '无'}`)\n        }\n        return truncate(lines.join('\\n\\n'), config.maxOutputChars)\n      }\n      if (type === 'all' && tasks.length) {\n        lines.push(`任务记录: ${tasks.length} 套（list_tasks 查看，select_task 续做）`)\n      }\n\n      if (!lines.length) {\n        const overview = storeOverview(store)\n        const hint =\n          type === 'experience'\n            ? 'Note a fix with remember so it can be recalled next time.'\n            : type === 'insight'\n              ? 'Save a lesson / decision / procedure with save_lesson so it can be recalled next time.'\n              : type === 'all'\n                ? 'Index it first with index_repo / index_doc, or note a fix with remember or save_lesson.'\n                : 'Index it first with index_repo / index_doc.'\n        const tail =\n          overview.files === 0\n            ? '. The store has never been indexed.'\n            : overview.latest\n              ? `, last indexed at ${overview.latest}. Use memory_stats to see what the store contains.`\n              : '. Use memory_stats to see what the store contains.'\n        const nestedNote = wantMemory && memHitCount === 0 ? nestedIndexNote(root, config) : ''\n        return (\n          `No memory matches for \"${args.query}\" in ${root}. ${hint}\\n` +\n          `Store overview: ${overview.files} files indexed, ${overview.entries} entries, ${overview.experience} experience notes${tail}${nestedNote}`\n        )\n      }\n      // 提示放在**最前**：`truncate()` 截的是尾部，而 insight/procedure 类条目单条就能到 600+\n      // 字符，放末尾会被整段截掉（实测 8000 字符预算下必被截）。\n      const note = wantMemory && memHitCount === 0 ? nestedIndexNote(root, config).trimStart() + '\\n\\n' : ''\n      return truncate(note + lines.join('\\n\\n'), config.maxOutputChars)\n    },\n  })\n}"
    },
    {
      "path": "src/auto-inject.js",
      "content": "// PR 2 静默注入引擎（entry 常驻块 + relevance 门控）\n// 安全约定：\n//  - 纯函数 buildInjection 可单测；\n//  - 唯一接线点是宿主 agent/pre-step 瀑布事件；任何异常/无会话 cwd → 交回合法决策，\n//    绝不让宿主请求受影响（宿主直接读 decision.kind，返回 undefined 会崩掉整步）。\n//  - “静默注入”文本带 [Memory Inject] 前缀，作为一条 plugin source 的 user 消息追加；\n//    按会话指纹去重，内容未变不重复追加。\nimport { createHash } from 'node:crypto'\nimport { createUserMessage } from '@deepseek-ai/dsh-llm'\nimport { ProjectMemoryStore } from './store.js'\nimport { hasProjectMarker, memoryRootFor, resolveProjectMemoryRoot, rootRejection } from './util/fs.js'\nimport { textOf } from './util/text.js'\nimport { stepContent } from './util/task-view.js'\nimport { insightMatchText, normalizedTokenOverlap } from './similarity.js'\nimport { createVectorCosine, createVectorRerank, vectorItemsFrom } from './vector-index.js'\nimport { BoundedMap, SessionCache } from './util/session-cache.js'\nimport { sessionWorkingDir } from './util/session-dir.js'\nimport { cfgInsight, GlobalStore, defaultGlobalFile, recordHit } from './insight-store.js'\nimport { projectTags } from './project-profile.js'\nimport { rankEntriesMergedScored } from './util/search.js'\nimport { insightToEntry, insightScoringText } from './recall.js'\nimport { buildReadinessContext, hintQueryText, corpusTermSets, idfCoveragePrepared, matchTrigger, normalizeTrigger, relativeHits } from './readiness.js'\nimport { activityFromCalls } from './ops.js'\nimport { appendInjectionAudit, appendShadowAudit, auditRecordFrom, cfgAudit, cfgShadow, shadowRecordFrom } from './audit.js'\n\nexport const INJECT_MARK = '[Memory Inject]'\n\n/**\n * 注入块抬头里的插件名。\n *\n * 消息的 `source.kind`（= {@link SOURCE_KIND}）只有宿主看得到：请求序列化只取 `role` 与\n * `content`（provider 侧对 `.source` 零引用），所以模型从元数据里读不到\"这是谁注入的\"。\n * 抬头是**唯一**能让模型（和 GUI 里的用户）看见生产者的地方。抬头不是行为契约：\n * 客户端不解析它，判据也不读它。\n */\nexport const PLUGIN_NAME = 'dsh-project-memory'\n\n/**\n * 本插件在 `message.source` 上声明的生产者 kind。\n *\n * 会话格式 v4 起 `MessageSourceMap` 是「每个生产者声明自己的 kind」的可合并联合类型，\n * **没有** `plugin` 这个兜底 kind：宿主的 `assertV4MessageSources` / `assertV4SourceRowAdmission`\n * 会直接拒绝 `kind === 'plugin'` 的消息（`session-format-v3-to-v4/src/message-sources.ts`），\n * 而拒绝发生在编码落盘那一刻 —— 于是整轮运行失败。\n *\n * 值选 `plugin:<包名>` 是因为这正是宿主自己的 v3→v4 迁移对本插件历史消息的改写结果\n * （`rewritePluginSource`：第三方插件 → `plugin:${plugin}`，并丢弃 `plugin` 字段）。\n * 新写的消息与迁移后的旧消息因此是**同一个生产者身份**，自激闸门（见 isOwnInjection）不需要按新旧分叉。\n */\nexport const SOURCE_KIND = 'plugin:dsh-project-memory'\n\n/**\n * 这条消息是不是本插件自己注入的？\n *\n * 三种写法都要认，因为同一条历史消息在不同阶段形状不同：\n *   - `plugin:dsh-project-memory` —— 现在写的，也是 v3→v4 迁移改写老消息的结果；\n *   - `project-memory` —— 保留的别名：将来若再换 kind，自激闸门不会因此失效；\n *   - `plugin: 'dsh-project-memory'` —— 迁移前内存里尚未落盘的旧形状（老宿主 / 测试夹具）。\n * @param {object|undefined|null} source - message.source\n * @returns {boolean}\n */\nexport function isOwnInjection(source) {\n  if (!source || typeof source !== 'object') return false\n  return source.kind === SOURCE_KIND\n    || source.kind === 'project-memory'\n    || source.plugin === 'dsh-project-memory'\n}\n\n/**\n * 注入正文的最小可用长度：预算塞不下这么多就宁可不注入（记 dropped）。\n * 与其输出 `- [ins_xxx] procedure ` 这种 stub，不如保持沉默——stub 只消耗 token 不传递信息。\n */\nconst MIN_BODY_CHARS = { trigger: 48, hint: 120 }\n\n/** 注入引擎配置：insight 默认之上叠加 autoContext 预算/门控参数。 */\nexport function cfgEngine(config) {\n  const c = (config && config.autoContext) || {}\n  const base = cfgInsight(config)\n  return {\n    ...base,\n    maxTokens: typeof c.maxTokens === 'number' ? c.maxTokens : 400,\n    entryMaxInsights: typeof c.entryMaxInsights === 'number' ? c.entryMaxInsights : 6,\n    // 提示通道的相对阈值（层内最高分的比例）：尺度无关，取代旧的\"绝对 overlap\"常量。\n    // 旧判据 normalizedTokenOverlap = |交集| / max(|A|,|B|) 对长消息必然趋零（实测 0.014–0.057）。\n    signalMinRatio: typeof c.signalMinRatio === 'number' ? c.signalMinRatio : 0.5,\n    // 兼容闸门：显式配置 relevanceMin 时仍走旧的绝对 overlap 判据；不配置则为 null（走相对阈值）。\n    relevanceMin: typeof c.relevanceMin === 'number' ? c.relevanceMin : null,\n    // resident 任务卡最多显示几个\"编辑中\"文件（纯写权重，最近写优先）\n    editedMax: typeof c.editedMax === 'number' ? c.editedMax : 3,\n    // 常驻任务卡总开关（entryOn:false = 只做条目注入，不回声任务卡）\n    entryOn: c.entryOn !== false,\n    // 模型自己写/维护任务清单后、尚无新人类消息时，不把任务卡再回声给模型（省 token）\n    skipEchoSelfTodo: c.skipEchoSelfTodo !== false,\n    // 预算审计日志级别（stderr）。默认 off：预算挤掉低优先级条目是正常降级，不是故障，\n    // 而终端是用户可见面——默认打印会让一次启动刷出多行，代价远大于那点可观测性收益。\n    //   off  : 永不打印（默认）\n    //   once : 每个会话最多一行（首次出现预算丢弃时），够定位又不刷屏\n    //   all  : 丢弃组合每变化一次打一行（作者排查用）\n    budgetLog: ['off', 'once', 'all'].includes(c.budgetLog) ? c.budgetLog : 'off',\n    // 同一条 insight 在本会话里重复注入的冷却（单位：pre-step 步数）。\n    // 0（默认）= 内容没变就不再注入：注入消息会留在会话历史里（宿主不压缩历史），\n    // 整块重发同一条 1200 字 procedure 只是重复占位。>0 用于历史可能被外部裁剪的场景。\n    reinjectItemsAfter: typeof c.reinjectItemsAfter === 'number' && c.reinjectItemsAfter >= 0 ? c.reinjectItemsAfter : 0,\n    // ---- S2/S3/S4 新增（准入化改造） ----\n    // 旧 `scope` 的处理：默认 **ignore**（保留历史数据、不静默改用户数据）；\n    // legacy `trigger.scope` 的值由作者手写，落不进自动派生的画像 tag 空间 → 当收窄条件用等于判死条目。\n    // 显式配 'filter' 才恢复旧的收窄语义。\n    legacyScope: c.legacyScope === 'filter' ? 'filter' : 'ignore',\n    // 条目通道的步间隔：两次\"条目注入\"之间至少隔这么多步（常驻任务卡不受限——它是状态快照，\n    // 内容变了就该更新）。这是\"不频繁\"的主要旋钮。\n    gateCooldownSteps: typeof c.gateCooldownSteps === 'number' && c.gateCooldownSteps >= 0 ? c.gateCooldownSteps : 2,\n    // 每会话条目注入的上限（条数 / 字符）：这是**保险丝**，不是节流阀。\n    // 节流由单轮 maxTokens 与 gateCooldownSteps 负责；这两个数的唯一职责是兜住病态的\n    // runaway，所以默认值必须远高于任何真实会话的用量。旧默认 12 条 / 4000 字符 ≈ 11 条，\n    // 实测真实日志里 11/81 个会话打满，打满之后是**永久**静默（实测 1234 步失明），\n    // 而\"会话后段\"恰是关键时刻概率最高的地方。实测最长会话用 35 条 / 8640 字符，故取\n    // 60 / 24000（≈1.7× 与 ≈2.8× 余量）。想复现旧行为显式配小值即可。\n    maxItemsPerSession: typeof c.maxItemsPerSession === 'number' && c.maxItemsPerSession >= 0 ? c.maxItemsPerSession : 60,\n    maxItemCharsPerSession: typeof c.maxItemCharsPerSession === 'number' && c.maxItemCharsPerSession >= 0 ? c.maxItemCharsPerSession : 24000,\n    // 提示通道的**绝对**覆盖底线（IDF 加权覆盖率）：相对阈值分不出\"有信号\"和\"矮子里拔将军\"，\n    // 只有归一在 [0,1]、有真零点才谈得上下限。0.30 时的实测反例：真实 store（43 条同源洞察）上，\n    // 对照组场景「改 pptx 时间戳」以 cov 0.32~0.35 注入了 3 条无关条目——语料同源时共享词多、\n    // IDF 分辨力被拉平，\"最不坏的一条\"就能过 0.30。0.45 落在实测分布的空隙里（假阳性 ≤0.35、\n    // 下一个真命中 ≥0.49），合成标注集在 0.6 以前 precision/recall 也仍是 1.00。\n    // 用 `--hint-cov` 在真实 store 上重放可复核（见 test/injection-scenarios.test.mjs）。\n    hintMinCoverage: typeof c.hintMinCoverage === 'number' && c.hintMinCoverage >= 0 ? c.hintMinCoverage : 0.45,\n    // 提示通道还要求至少这么多个共同词：单个通用词（\"插件\"）也能拿到 coverage=1.00。\n    hintMinMatched: typeof c.hintMinMatched === 'number' && c.hintMinMatched >= 0 ? c.hintMinMatched : 2,\n    // 通道级沉默：查询里能在语料中找到对应的词占比低于这个值时，整条提示通道本轮不出声。\n    // 长句子里只有一两个词碰巧命中，coverage 会虚高到 1.00——这条门就是为它设的。\n    hintMinSupport: typeof c.hintMinSupport === 'number' && c.hintMinSupport >= 0 ? c.hintMinSupport : 0.15,\n    // 可选向量层（leanvec）。`vectorDir` 无默认值 = 默认不用向量（纯词法）；\n    // 只有配置了目录（或环境变量、或装上可选依赖）才构造 rerank，见 src/vector-index.js。\n    vectorDir: typeof c.vectorDir === 'string' && c.vectorDir ? c.vectorDir : null,\n    vectorAlpha: typeof c.vectorAlpha === 'number' && c.vectorAlpha >= 0 && c.vectorAlpha <= 1 ? c.vectorAlpha : 0.5,\n    // 写入侧近重复检测的独立开关（默认开）。**不跟随 vectorAlpha**：那条是排序权重，\n    // 设成 0 只该关掉重排，不该连带停掉 0.9 自动覆盖 / 0.7 近邻提示。\n    vectorDedup: c.vectorDedup !== false,\n    // 两个**实验性**旋钮：没有可发布的默认值（证据见 scoreHints 的注释），所以不设就不启用。\n    vectorItemMin: typeof c.vectorItemMin === 'number' && Number.isFinite(c.vectorItemMin) ? c.vectorItemMin : undefined,\n    vectorSpeakMin: typeof c.vectorSpeakMin === 'number' && Number.isFinite(c.vectorSpeakMin) ? c.vectorSpeakMin : undefined,\n  }\n}\n\n/**\n * 给写入路径（`save_lesson` / `remember`）用的向量打分器：**没装/没配就是 null**。\n *\n * 与注入路径共用一个解析入口（`openEngine`），但**不共用开关**：写入去重由\n * `autoContext.vectorDedup` 控制，不受 `vectorAlpha`（排序权重）影响。返回的函数是同步的，\n * 供 `saveInsight` 在写事务里直接调用；任何异常都降级成 null，绝不因为可选的向量层挡住写入。\n * @param {object} config - 插件配置\n * @param {{storeDir: string|null, items: object[]}} o - 持久化位置与候选池（见 vectorItemsFrom）\n * @returns {Promise<((text: string, items: object[]) => Map<string, number>)|null>}\n */\nexport async function createWriteCosine(config, { storeDir = null, items = [] } = {}) {\n  const engine = cfgEngine(config)\n  try {\n    return await createVectorCosine({ storeDir, items, vectorDir: engine.vectorDir, dedup: engine.vectorDedup })\n  } catch {\n    return null\n  }\n}\n\n/**\n * 从一份消息列表里取\"人说的话\"。\n *\n * 只认 `role=user` **且**（`source.kind === 'user'` 或无 source 的老宿主/测试）。\n * 其它 user 角色的消息不是人说的：`agent-message`（子代理报告 relay）、`subagent-settled`、\n * `tool-jobs`（后台任务完成）、`time-context`、`runtime-context` 都会出现在 claimed delta 里。\n * 实测代价：子代理报告里的\"发布/渲染\"曾被当成用户意图，触发 `intent:release`（1050 字符）\n * 与 `intent:渲染`（1200 字符）两条无关 procedure。\n *\n * `agent/pre-step` 的 `messages` 是 claimed **delta**，不是完整历史，所以会话中段通常\n * 根本没有真人消息 —— 调用方应回退到每会话缓存（见 `InjectionSessions.humanText`）。\n * @param {object[]} messages\n * @returns {string} 人类消息正文；没有则空串\n */\nexport function lastUserText(messages) {\n  if (!Array.isArray(messages)) return ''\n  for (let i = messages.length - 1; i >= 0; i--) {\n    const m = messages[i]\n    if (!m || m.role !== 'user') continue\n    const t = textOf(m)\n    if (!t.trim()) continue\n    // 本插件注入的块也是 role=user：绝不能再拿它当查询（自激）。\n    if (isOwnInjection(m.source)) continue\n    const kind = m.source && m.source.kind\n    if (kind && kind !== 'user') continue\n    return t.trim()\n  }\n  return ''\n}\n\nfunction fingerprint(text) {\n  return createHash('sha256').update(text).digest('hex').slice(0, 12)\n}\n\nfunction linesOf(list) {\n  const out = []\n  for (const it of list || []) {\n    if (!it || it.archived || it.draft) continue\n    const body = it.fix || it.solution || it.choice || (Array.isArray(it.steps) ? `步骤 ${it.steps.length} 条` : '')\n    out.push(`- [${it.id}] ${it.kind}: ${it.title}${body ? ` — ${String(body).slice(0, 120)}` : ''}`)\n  }\n  return out\n}\n\n/** 任务卡上\"编辑中\"文件（写过、最近写优先，最多 max 个）。 */\nexport function editedFiles(task, max) {\n  if (!task || !task.fileMeta) return []\n  const meta = task.fileMeta\n  // task.files 已由 taskbridge 保持热序（写过在前、按 lastWriteAt 倒序）\n  return (task.files || []).filter((f) => meta[f] && meta[f].lastWriteAt).slice(0, max)\n}\n\n/**\n * 是否回声 resident 任务卡：最近一次推进是模型自己 todo 写步骤、且之后没有新人类消息时，\n * 不回声（模型刚写的东西再喂回去 = 噪音/浪费 token）。保留相关 insights 注入不变。\n */\nexport function shouldEchoTaskCard(task, cfg) {\n  if (!task) return false\n  const c = cfg || {}\n  if (c.skipEchoSelfTodo === false) return true\n  const lt = task.lastTodoAt\n  const lh = task.lastHumanAt\n  if (lt && lh) return !(lt > lh)\n  return true\n}\n\n/** 任务卡 + 非草稿任务级 insights 摘要（常驻块主体）。\n * withEdited=false 只留给需要稳定正文的调用方；去重指纹现在**包含**“编辑中”行：\n * 否则常驻卡会永远停在第一次注入时的文件列表（写文件不会改变指纹）。 */\nexport function buildEntryContent(task, cfg, { withEdited = true } = {}) {\n  if (!task) return ''\n  const c = cfg || {}\n  const steps = (task.steps || []).map((s) => stepContent(s).slice(0, 80))\n  const progress = steps.length ? `${steps.length} 步` : ''\n  const card = [\n    `任务: ${task.title || '(untitled)'}`,\n    `进度: ${progress}`,\n    ...steps.slice(0, 12).map((s, i) => `  ${i + 1}. ${s}`),\n  ]\n  const insights = linesOf(task.insights)\n  // 0 是合法值（= 不显示）：cfgEngine 已归一成数字，这里不能再用 `||` 把 0 顶回默认。\n  const maxEdited = Number.isFinite(c.editedMax) ? c.editedMax : 3\n  const maxInsights = Number.isFinite(c.entryMaxInsights) ? c.entryMaxInsights : 6\n  const edited = editedFiles(task, maxEdited)\n  const parts = [...card]\n  if (withEdited && edited.length) parts.push(`  编辑中: ${edited.join(', ')}`)\n  if (insights.length) parts.push(`任务记忆:`, ...insights.slice(0, maxInsights))\n  return parts.join('\\n')\n}\n\n/** 候选池：project + global + 绑定任务（同一 id 只取一次；归档/草稿不进注入）。\n * 候选在进入匹配前统一走旧 trigger → 新 schema 的归一（幂等，纯内存，不落盘）。 */\nfunction insightCandidates(store, globalStore, task, opts) {\n  const out = []\n  const seen = new Set()\n  const push = (it) => {\n    if (!it || it.archived || it.draft) return\n    const key = it.id || `${it.kind}:${it.title}`\n    if (seen.has(key)) return\n    seen.add(key)\n    out.push(normalizeTrigger(it, { legacyScope: opts?.legacyScope }))\n  }\n  for (const it of (store ? store.insightItems() : []) || []) push(it)\n  for (const it of (globalStore ? globalStore.items() : []) || []) push(it)\n  for (const it of (task && task.insights) || []) push(it)\n  return out\n}\n\n/** 一条 insight 的注入正文：procedure 给全步骤，其余给标题 + 结论。 */\nfunction insightBody(it) {\n  return it.kind === 'procedure' && Array.isArray(it.steps)\n    ? `【${it.title}】\\n${it.steps.map((s, i) => `${i + 1}. ${s}`).join('\\n')}`\n    : `- [${it.id}] ${it.title}${it.fix || it.solution || it.choice ? ` — ${it.fix || it.solution || it.choice}` : ''}`\n}\n\n/** 条目级去重键：注入正文的指纹（正文变了才允许再注入一次，见 cfg.reinjectItemsAfter）。 */\nexport function insightItemHash(it) {\n  return createHash('sha256').update(insightBody(it)).digest('hex').slice(0, 12)\n}\n\n/** 把正文塞进剩余预算：放不下就截断；连\"有用前缀\"都留不下就返回 null（由调用方记 dropped）。 */\nexport function fitBody(body, remaining, min = MIN_BODY_CHARS.hint) {\n  if (remaining < min) return null\n  if (body.length <= remaining) return body\n  return `${body.slice(0, remaining - 1)}…`\n}\n\n/**\n * 通道 1：authored trigger 命中（确定性、全文、优先级 1）。procedure 先于其它 kind（步骤更完整）。\n * 准入化（S2）：只有 `when`（op / 写目标 / 意图词）能触发，guard 只能收窄；\n * **没有 `when` 的条目在这里永远不命中**（降级为可发现 + 按需拉取）。\n */\nfunction collectTriggered(cands, ctx) {\n  const hits = []\n  for (const it of cands) {\n    const why = matchTrigger(it.trigger, ctx)\n    if (why) hits.push({ it, why })\n  }\n  hits.sort(\n    (a, b) => (a.it.kind === 'procedure' ? 0 : 1) - (b.it.kind === 'procedure' ? 0 : 1)\n      || String(a.it.id).localeCompare(String(b.it.id)),\n  )\n  return hits\n}\n\n/**\n * 通道 2：统计信号（提示态、优先级 2）。**双门槛**：层内相对阈值 + IDF 加权覆盖率（绝对下限）。\n * 查询只用「人类消息的意图文字 + 本次写目标」：原始工具参数不是查询文本，它们正是\n * `dcterms→rm`、`*.pptx→论文笔记` 那类假阳性的来源。被门槛拦下的记进 dropped，不静默。\n *\n * 可选的第三层：`rerank`（向量重排，默认关闭）。**职责严格分离**——闸门（支持度/覆盖率/共同词数）\n * 仍由词法决定，`rerank` 只改层内排序与 `relative` 那一关。理由见下方融合处注释。\n * @param {{ score: (q: string, cands: object[]) => Map<string, number>, alpha?: number, itemMin?: number, speakMin?: number }} [rerank]\n *   `itemMin` 给定且条目的余弦低于它时，该条目**不进提示通道**（只作用于提示通道，不碰 trigger）。\n *   `speakMin` 给定时，若层内最高余弦 ≥ 它，则本轮免于被通道级 `hintMinSupport` 静音（见下方救援处）。\n *\n *   ⚠ 两个旋钮的实测边界（**都还没有可发布的默认值，别拍一个数字上去**）：\n *   · `itemMin`：**真实交付上分辨力为零 → 不要开**。合成池上它看着很灵（假阳性 cos 0.351 vs\n *     真命中 0.530），但真实 store 双重否定：① **绝对常量不可移植**——交付的 45 条余弦\n *     p50=0.206，同一个 0.42 会剪掉 45/45 = 100%（根因是文本变体：真实条目走 insightScoringText\n *     的长文本，均值池化被稀释向语料均值）；② **换成尺度无关量也不行**——在人工标注的 30 条真实\n *     交付上（对 10 / 错 20，基线精度 0.33），cos 与 cos/步内最高的高半/低半精度**完全相同**\n *     （0.33 vs 0.33），\"对\"与\"错\"的 cosRel 分布重叠（p50 0.793 vs 0.782）。唯一有信号的是\n *     **步内名次 ≤4**（精度 0.46 vs 0.24），但拿它当门要误杀 4/10 个真命中 → 不划算。\n *     ③ **标签本身不稳**：同一个 30 条样本，agent 判 10 条有用、本地 4B 模型判 7 条，\n *     逐条一致率只有 57%、Cohen kappa = **-0.05（等于随机）**。两次独立估计的水平接近\n *     （33% vs 23.8%，126 条上是 23.8%），所以\"真实交付精度约 1/4~1/3\"这个**水平**可信，\n *     但**逐条标签不可信** → 任何在它上面标定的阈值都不可用。\n *   · `speakMin`：**证据仍不足 → 别开**。5 个自然语言对照的最高余弦\n *     0.356 / 0.341 / **0.467** / 0.343 / 0.398，最低目标 0.483 → 间隔只有 0.016，且全靠一个\n *     边界样本撑着；再补一个对照就可能翻转。\n */\nfunction scoreHints({ cands, query, humanText, hintQuery, cfg, dropped, rerank = null }) {\n  const hints = []\n  // 影子记录用：本步**全部**被评过分的候选 + 特征 + 判据结果。与 hints/dropped 分开算——\n  // 现有两类记录都只覆盖\"过得了相对阈值的那部分\"，恰恰缺了\"因为没到阈值而从未被考虑\"的候选，\n  // 而那正是离线重放阈值时需要的那批。这里只做加法，不动任何现有判据。\n  const candidates = []\n  // 真正用于评分的查询文本。影子记录必须留下它：`query`（人类消息原文）与它不是一回事，\n  // 写目标驱动的那些步 `query` 为空、候选却非空。少了它，判据无法离线重放。\n  const q = hintQueryText(hintQuery)\n  if (!cands.length) return { hints, candidates, scoreQuery: q }\n  if (typeof cfg.relevanceMin === 'number') {\n    // 兼容：显式 relevanceMin → 旧的绝对 overlap 判据（老 profile 行为不变）\n    for (const it of cands) {\n      const score = normalizedTokenOverlap(humanText || query || '', insightMatchText(it))\n      if (score >= cfg.relevanceMin) hints.push({ it, score, why: `overlap:${score.toFixed(3)}` })\n    }\n    hints.sort((a, b) => b.score - a.score)\n    return { hints, candidates, scoreQuery: q } // 旧判据路径不产出影子候选（已废弃，无重放价值）\n  }\n  if (!q) return { hints, candidates, scoreQuery: q }\n  const byId = new Map(cands.map((it) => [it.id, it]))\n  // 覆盖率语料必须与 BM25 排序同源（insightScoringText）：否则\"只在 fix/solution 里有匹配\"\n  // 的查询词 df=0 → supportRatio=0 → 整条提示通道沉默，而排序明明给了它高分。\n  const corpus = cands.map((it) => insightScoringText(it))\n  // 查询与被测覆盖率的文本用**同一个**过滤后的查询：否则缩写（wsl/npm）会在 BM25 里被剔除、\n  // 却仍在覆盖率里计分，\"至少两个共同词\"就被它们凑够了。\n  const scored = rankEntriesMergedScored(cands.map(insightToEntry), [q], cands.length)\n  // ---- 向量重排（可选、默认关闭）：只改**排序**与 `relative` 那一关，绝不碰 support/coverage/thin ----\n  // 为什么不做成\"向量分当绝对闸门\"：实测在带标注的 8 场景/24 条池上，expect 为空的对照场景\n  // 纯向量 top-1 = 0.38，而多条**真命中**只有 0.20~0.38（余弦与真值区间重叠）→ 任何绝对余弦\n  // 阈值要么放过对照、要么杀掉真命中。所以闸门继续由词法/支持度决定（它们不随嵌入模型变），\n  // 向量只在 BM25 的 top-k 内决定\"先说哪条\"。换模型/改词表只影响这一层，不必重标绝对阈值。\n  //\n  // `rerank.score(q, cands)` 由调用方提供（插件运行时装了 leanvec 才给；没装就不传，行为不变）：\n  //   返回 Map<insightId, cos∈[0,1]>；**查询无法编码时应返回空 Map**——那样所有条目都没有\n  //   向量分，排序退化回纯词法，不会被压平成一个平台。\n  if (rerank && typeof rerank.score === 'function') {\n    const alpha = Math.max(0, Math.min(1, typeof rerank.alpha === 'number' ? rerank.alpha : 0.5))\n    let cos = null\n    try { cos = rerank.score(q, cands) } catch { cos = null } // 向量层任何异常都不得影响注入\n    const top0 = scored[0]?.score || 1\n    for (const r of scored) {\n      const v = cos instanceof Map ? cos.get(r.entry.insightId) : undefined\n      const has = typeof v === 'number' && Number.isFinite(v)\n      // 先留一份**未融合**的 BM25 原分：影子记录的 `rel` 必须继续是词法相对分，\n      // 否则离线重放（tools/vector-eval.mjs）拿到的\"BM25 臂\"会被融合分污染。\n      r.bm25 = r.score\n      r.vector = has ? v : null\n      // 有向量分的：归一后的词法分与余弦按 α 混合；没有的：只保留归一后的词法分\n      // （不拿 0 分去罚它——缺向量不等于不相关）。\n      r.score = has ? (1 - alpha) * (r.score / top0) + alpha * v : r.score / top0\n    }\n    scored.sort((a, b) => b.score - a.score)\n  } else {\n    for (const r of scored) r.vector = null\n  }\n  // 语料词集合建**一次**再逐条算覆盖率。逐条调用 `idfCoverage` 会让它每次重建整个语料，\n  // 即 O(C²) 次 tokenize（实测真实 store 单步 147ms → 1.3ms，109×，结果逐字段一致）。\n  const corpusSets = corpusTermSets(corpus)\n  const coverage = new Map(cands.map((it, i) => [it.id, idfCoveragePrepared(q, corpus[i], corpusSets)]))\n  const qStats = coverage.get(cands[0].id) || { supported: 0, terms: 0 }\n  const supportRatio = qStats.terms > 0 ? qStats.supported / qStats.terms : 0\n  // 通道级沉默：查询里绝大多数词在语料里根本没有对应 → \"覆盖率 1.00\"只是假象。\n  //\n  // ⚠ 它是**比率**（supported / 查询去重词数），所以长句在**小语料**上必然低：自然语言消息实测\n  // 只有 0.11~0.13——目标条目本身 rel=1.00 / coverage=1.00 / matched=2 也会被整条静音。\n  // 因此加一条**可选**的语义救援：仅当调用方提供了向量层、且层内最高余弦达到 `speakMin` 时，\n  // 才允许本轮不沉默（含义是\"词法视角太稀，但语义视角很有把握\"）。它**不放松任何逐条闸门**\n  // （coverage / matched / relative 照旧），没有向量时的行为也一字不改。\n  let vectorRescue = false\n  if (rerank && typeof rerank.speakMin === 'number') {\n    let topCos = 0\n    for (const r of scored) if (typeof r.vector === 'number' && r.vector > topCos) topCos = r.vector\n    vectorRescue = topCos >= rerank.speakMin\n  }\n  const channelThin = typeof cfg.hintMinSupport === 'number' && supportRatio < cfg.hintMinSupport && !vectorRescue\n  for (const r of relativeHits(scored, { ratioMin: cfg.signalMinRatio })) {\n    const it = byId.get(r.entry.insightId)\n    if (!it) continue\n    const ev = coverage.get(it.id) || { coverage: 0, matched: 0, supported: 0, terms: 0 }\n    if (channelThin) {\n      dropped.push({ id: it.id, channel: 'hint', reason: `support:${supportRatio.toFixed(2)}` })\n      continue\n    }\n    // 绝对门槛：覆盖率下限 + 共同词数下限（查询本身很短时下限按可用词数收敛）。\n    if (typeof cfg.hintMinCoverage === 'number' && ev.coverage < cfg.hintMinCoverage) {\n      dropped.push({ id: it.id, channel: 'hint', reason: `coverage:${ev.coverage.toFixed(2)}` })\n      continue\n    }\n    // 共同词数下限按**查询本身的词数**收敛（查询很短时不强求两个），而不是按\"语料能表示的词数\"：\n    // 后者在长而杂的查询上会退化成 1，一个碰巧命中的通用词就能过闸。\n    const needMatched = Math.min(typeof cfg.hintMinMatched === 'number' ? cfg.hintMinMatched : 2, ev.terms)\n    if (ev.matched < needMatched) {\n      dropped.push({ id: it.id, channel: 'hint', reason: `thin:${ev.matched}` })\n      continue\n    }\n    // item 级余弦地板（可选）：语义上根本不相关的条目，无论词法多像都不进提示通道。\n    // 这是**只作用于提示通道**的额外一关：authored trigger 是确定性全文注入契约，绝不能被向量拦。\n    // 实测（24 条池）分辨力真实：词法巧合的假阳性 `l_curated`（查询\"把列表按日期倒序排\"）余弦\n    // 0.351，而真命中 `l_changelog` 0.530，间隔 0.179。取不到向量时不设限——缺向量不等于不相关。\n    if (rerank && typeof rerank.itemMin === 'number' && typeof r.vector === 'number' && r.vector < rerank.itemMin) {\n      dropped.push({ id: it.id, channel: 'hint', reason: `vector:${r.vector.toFixed(2)}` })\n      continue\n    }\n    hints.push({ it, score: r.score, why: `relative:${(r.score / (scored[0].score || 1)).toFixed(2)} cov:${ev.coverage.toFixed(2)}/${ev.matched}` })\n  }\n\n  // ---- 影子候选（只读、无副作用）：重放一遍**全部**被评分的条目，标出它卡在哪一关 ----\n  // 顺序与真实判据一致（support → coverage → thin → relative），最后 'cand' = 过了全部门槛\n  // （注意 'cand' 不等于\"真的注入了\"：还要过去重/预算/冷却，那些写在同一行的 injected/silence）。\n  {\n    // 两个分母必须分开：真实判据（`relative`）用的是**融合后**的分，而影子记录的 `rel`\n    // 承诺的是**词法**相对分。此前两者共用 `scored[0].score`，于是 `rel` 的分子是 BM25 原分、\n    // 分母是融合 top —— 实测同一行里 `rel` 能到 5.925（应当 ≤1），离线拿它重放阈值会全歪。\n    const top = scored[0]?.score || 0\n    let lexTop = 0\n    for (const r of scored) {\n      const lex = r.bm25 ?? r.score\n      if (Number.isFinite(lex) && lex > lexTop) lexTop = lex\n    }\n    const ratio = typeof cfg.signalMinRatio === 'number' && Number.isFinite(cfg.signalMinRatio) ? cfg.signalMinRatio : 0.5\n    for (const r of scored) {\n      const it = byId.get(r.entry.insightId)\n      if (!it || !Number.isFinite(r.score) || r.score <= 0) continue\n      const ev = coverage.get(it.id) || { coverage: 0, matched: 0, supported: 0, terms: 0 }\n      const needMatched = Math.min(typeof cfg.hintMinMatched === 'number' ? cfg.hintMinMatched : 2, ev.terms)\n      let decision = 'cand'\n      if (channelThin) decision = 'support'\n      else if (typeof cfg.hintMinCoverage === 'number' && ev.coverage < cfg.hintMinCoverage) decision = 'coverage'\n      else if (ev.matched < needMatched) decision = 'thin'\n      else if (rerank && typeof rerank.itemMin === 'number' && typeof r.vector === 'number' && r.vector < rerank.itemMin) decision = 'vector'\n      else if (r.score < top * Math.max(0, Math.min(1, ratio))) decision = 'relative'\n      const cand = {\n        id: it.id,\n        channel: 'hint',\n        // `rel` 恒为**词法**相对分（未融合，分母是词法 top），供离线重放对照；\n        // 融合后的分另记 fused，`decision: 'relative'` 用的仍是融合分（与真实判据一致）。\n        rel: Number(((r.bm25 ?? r.score) / (lexTop || 1)).toFixed(3)),\n        coverage: Number(ev.coverage.toFixed(3)),\n        matched: ev.matched,\n        support: ev.supported,\n        terms: ev.terms,\n        decision,\n      }\n      // 只在启用重排时加字段：默认路径的记录与旧版逐字节一致（不引入 undefined 键）。\n      if (rerank) {\n        cand.fused = Number(r.score.toFixed(3))\n        cand.vector = r.vector == null ? null : Number(r.vector.toFixed(3))\n        // 本轮是否靠语义救援才免于被 `support` 整条静音（0=没救、1=救了）。离线重放要靠它\n        // 区分\"support 门拦的\"与\"coverage 门拦的\"。\n        cand.rescue = vectorRescue ? 1 : 0\n      }\n      candidates.push(cand)\n    }\n  }\n  return { hints, candidates, scoreQuery: q }\n}\n\n/**\n * 构建注入内容（不写盘、无副作用）。\n *\n * 交付契约：**authored trigger（所有 kind）= 确定性全文注入，优先级 1；统计信号 = 截断提示，\n * 优先级 2**。预算排程为：常驻任务卡 → trigger 命中 → 提示。每一步都记 `reasons`（为什么注入）\n * 与 `dropped`（为什么没注入），让\"注入/未注入\"可审计——而不是只有静默的门槛。\n * @param {object} opts { query, readiness, task, store, globalStore, projectTagsList, cfg, skipItem? }\n * @param {(it: object) => boolean} [opts.skipItem] 条目级去重：返回 true 的条目直接退出排程\n *   （本会话已注入过且正文未变）。在排程前过滤，省下的预算留给新条目。\n * @returns {{ text: string, labels: string[], reasons: object[], dropped: object[] }}\n */\nexport function buildInjection(opts) {\n  const { query, task, globalStore, cfg } = opts\n  const store = opts.store || null\n  const tags = opts.projectTagsList || []\n  // 就绪上下文可能**已经构建过**（injectForStep 先构建、再传给这里）。二次构建会把第一遍的\n  // `actions` 输出当成\"调用方声明的动作\"重新信任一遍 —— 散文里的 file-delete 会因此绕过\n  // PRE_ACTION_OPS 过滤（实测：\"清理一下 README 的措辞\"仍注入 1200 字符恢复 procedure）。\n  // 结构化标记：带 ops + intentOps 的上下文是构建产物，只补 tags，不再重新归一。\n  const built = opts.readiness && Array.isArray(opts.readiness.ops) && Array.isArray(opts.readiness.intentOps)\n  const ctx = built\n    ? { ...opts.readiness, tags: [...new Set([...(opts.readiness.tags || []), ...tags])] }\n    : buildReadinessContext({ ...(opts.readiness || { humanText: query || '' }), tags })\n  const labels = []\n  const reasons = []\n  const dropped = []\n  const parts = []\n  // 预算只能是上限，不是目标。两条额度分开：\n  //   stepBudget —— 单轮（常驻块 + 条目）共享的 maxTokens；\n  //   itemBudget —— 条目还受会话字符额度约束；**常驻块不占这条**（它是状态快照，文档明说不受限）。\n  // 旧实现把两者取小成同一个 budgetChars，会话额度用尽后连任务卡都被截成 `…(截断)`。\n  const quotaChars = typeof opts.maxChars === 'number' ? opts.maxChars : Infinity\n  const maxItems = typeof opts.maxItems === 'number' ? opts.maxItems : Infinity\n  const skipItems = opts.skipItems === true\n  const stepBudget = Math.max(0, (cfg.maxTokens || 400) * 3)\n  const itemBudget = Math.max(0, Math.min(stepBudget, quotaChars))\n\n  const skipItem = typeof opts.skipItem === 'function' ? opts.skipItem : null\n  const cands = insightCandidates(store, globalStore, task, cfg).filter((it) => !(skipItem && skipItem(it)))\n\n  // 两条通道：authored trigger（确定性、全文、优先级 1）→ 统计信号提示（优先级 2）。\n  const triggered = collectTriggered(cands, ctx)\n  if (skipItems) {\n    // 会话级限流命中：条目通道本轮整体沉默，但把\"本该注入什么\"记进 dropped——不做静默降级。\n    for (const { it } of triggered) dropped.push({ id: it.id, channel: 'trigger', reason: opts.silenceReason || 'cooldown' })\n  }\n  // procedure 不进提示通道：它要过 trigger.scope（见 scoreHints 注释）。\n  const consumed = new Set(triggered.map((t) => t.it.id))\n  // 限流命中时**照旧评分**（只算不注入，`place()` 仍按 skipItems 跳过）：影子记录要能回答\n  // \"这一步如果不限流会注入什么\"——那正是限流期间最需要回答的问题。此前这里直接置空，\n  // 实测 1420 个静默步一个候选都没留下。\n  const hintCands = cands.filter((it) => !consumed.has(it.id) && it.kind !== 'procedure')\n  const { hints, candidates, scoreQuery } = scoreHints({\n    cands: hintCands,\n    query,\n    humanText: ctx.humanText,\n    hintQuery: [ctx.intent || ctx.humanText || '', ...(ctx.targets || [])].filter(Boolean).join(' '),\n    cfg,\n    dropped,\n    rerank: opts.rerank || null,\n  })\n\n  // 常驻块文本。去重指纹包含“编辑中”行：否则这条常驻状态只会在别的条目变化时顺带更新，\n  // 模型会一直看到旧文件列表。editedFiles 只返回文件名（不含时间戳），所以同一个文件\n  // 反复写不会改变指纹；只有热点文件集合/顺序变化时才重发整块。\n  const echo = cfg.entryOn !== false && shouldEchoTaskCard(task, cfg)\n  const entry = echo ? buildEntryContent(task, cfg) : ''\n  const entryStable = entry\n  let used = entry.length\n  let itemUsed = 0\n  let itemCount = 0\n\n  /** 把一组候选按优先级放进剩余预算：放不下的进 dropped（quota / budget），不静默。 */\n  const place = (channel, list, minChars, labelOf) => {\n    for (const { it, why } of list) {\n      if (itemCount >= maxItems) {\n        dropped.push({ id: it.id, channel, reason: 'quota' })\n        continue\n      }\n      // 条目同时受\"单轮剩余\"与\"会话字符剩余\"约束；常驻块只占前者。\n      const remaining = Math.min(stepBudget - used, itemBudget - itemUsed)\n      const body = fitBody(insightBody(it), remaining, minChars)\n      if (body === null) {\n        // 带出数字：旧的 `budget` 没有量纲，\"还剩 38 字符、这条最少要 120\" 与\"根本没预算\"\n        // 在日志里长得一样 —— 配额逼近上限时那条永久静默的细缝因此完全不可诊断。\n        dropped.push({ id: it.id, channel, reason: 'budget', remaining, need: minChars })\n        continue\n      }\n      used += body.length + 1\n      itemUsed += body.length + 1\n      itemCount++\n      parts.push(body)\n      labels.push(labelOf(it))\n      reasons.push({ id: it.id, channel, why, hash: insightItemHash(it), chars: body.length })\n    }\n  }\n  // 限流命中时条目通道整体沉默：triggered 已在上方记进 dropped，这里不再重复排程。\n  if (!skipItems) {\n    place('trigger', triggered, MIN_BODY_CHARS.trigger, (it) => it.kind)\n    place('hint', hints, MIN_BODY_CHARS.hint, () => 'hint')\n  }\n\n  // 预算层结局写回候选。`decision` 是**门槛层**的结论（support/coverage/thin/relative/cand），\n  // `outcome` 是**预算层**的结论——两者正交。\"过了全部门槛却没注入\"必须能归因，\n  // 否则日志只能证明门槛做了什么，证明不了预算拿走了什么。\n  {\n    const outcomeById = new Map()\n    for (const r of reasons) outcomeById.set(`${r.channel}\\u0000${r.id}`, 'injected')\n    for (const d of dropped) {\n      const key = `${d.channel}\\u0000${d.id}`\n      if (!outcomeById.has(key)) outcomeById.set(key, d.reason)\n    }\n    for (const c of candidates) {\n      c.outcome = skipItems ? 'idle'\n        : c.decision !== 'cand' ? 'gate'\n          : outcomeById.get(`hint\\u0000${c.id}`) || 'unscheduled'\n    }\n  }\n\n  const total = [entry, ...parts].filter(Boolean)\n  // 早退也必须带上 candidates/scoreQuery：空块不等于\"没有候选\"（无任务卡 + 全部被预算挤掉\n  // 就是这种形状），此前这里把两者一起丢了。\n  if (!total.length) {\n    return { text: '', entry, labels, reasons, dropped, candidates, scoreQuery, itemChars: itemUsed }\n  }\n  // 整块只受单轮预算（maxTokens）约束；会话条目额度已在 place() 里单独扣过。\n  const clamp = (t) => (t.length > stepBudget ? `${t.slice(0, stepBudget)}\\n…(截断)` : t)\n  const dedupeText = clamp([entryStable, ...parts].filter(Boolean).join('\\n'))\n  return { text: clamp(total.join('\\n')), entry, entryStable, labels, reasons, dropped, candidates, scoreQuery, dedupeText, itemChars: itemUsed }\n}\n\n// 每会话状态的会话数上限：六张表共用（旧实现把同一个 200 在五处各写一遍）。\nconst SESSION_STATE_MAX = 200\n// 单会话已注入条目表的条数上限。\nconst INJECTED_ITEMS_MAX = 600\n// 单会话保留的 tool/call 观察窗口（够覆盖\"最近几步在做什么\"）。\nconst OBSERVED_CALLS_MAX = 8\n\n/**\n * 注入引擎的「每会话一份」状态。\n *\n * 之前六张表散在 installAutoInject 里、各自 hand-roll 淘汰循环，同一个\n * `while (map.size > CAP) map.delete(map.keys().next().value)` 抄了五遍：容量上限写在五处，\n * 抄漏一处就是无界增长，dispose 时也漏清两张表。容量只在这里定义一次。\n */\nclass InjectionSessions {\n  constructor() {\n    const cache = (create) => new SessionCache({ maxSessions: SESSION_STATE_MAX, create })\n    // 上次注入指纹：用单个变量会让并发会话互相抑制注入。\n    this.lastText = cache()\n    // 上次预算丢弃签名：预算把条目挤出去时必须留痕一次，而不是静默（degraded 可见性）。\n    this.lastDropped = cache()\n    // 条目级去重记忆：insightId → { hash, step }。注入的消息留在 append-only 的会话历史里，\n    // 所以\"整块指纹变了\"不等于\"内容都是新的\"：滑动工具窗口 / 任务卡更新 / 预算截断边界都会\n    // 让同一份 procedure 被整块重发（实测 66 步注入 20 次，同一份 1732 字重发 3 次）。\n    this.items = cache(() => new BoundedMap(INJECTED_ITEMS_MAX))\n    // 会话步数：为 reinjectItemsAfter 提供时间轴。\n    this.step = cache(() => 0)\n    // 会话级条目额度（S3）：条数 / 字符 / 上次\"条目注入\"的步号。常驻任务卡不占额度——\n    // 它是状态快照，内容变了就该更新；被限流的是记忆条目的推送。\n    this.quota = cache(() => ({ items: 0, chars: 0, lastStep: -Infinity }))\n    // 反应窗口：本会话最近观察到的 tool/call（参数里有 git commit / npm publish / 改动的路径）。\n    // 宿主没有\"工具执行前拦截\"钩子，所以这是 pre-step 之外唯一能拿到的动作事实。\n    this.observed = cache(() => [])\n    // 本会话最后一条**真人**消息。`agent/pre-step` 拿到的是 claimed delta，会话中段通常没有\n    // 真人消息，于是\"本步的意图\"会退化成子代理报告 / job 通知 / 时间快照里的词（实测 386 步里\n    // 只有 31 步有真人 query，其余全是通知）。意图必须是会话状态，不是这一步恰好收到的文本。\n    this.humanText = cache()\n    // 本会话是否已通告\"记忆根是推定的\"（会话工作目录，无项目标记）。状态声明只发一次。\n    this.rootNoticed = cache(() => false)\n    this._all = Object.values(this)\n  }\n\n  clear() {\n    for (const cache of this._all) cache.clear()\n  }\n}\n\n/**\n * 记录会话里的两类事实：\n *  - `user/message`（**真人的**）→ 每会话最后一条人类消息。它是会话状态，不是本步增量；\n *  - `tool/call` → 最近 8 次调用，ops.js 从结构化参数解析 op / 写目标 / 主机。\n *\n * 两者都只从**事件**里来，不再把任意工具的参数拼成文本再解析（那会让 subagent 提示词里\n * 的\"删除/迁移\"变成父会话的动作，实测存活 8 步）。\n */\nfunction installCallObserver(ctx, sessions) {\n  ctx.on('session/event', (session, event) => {\n    try {\n      const sessionId = session && session.id\n      if (!sessionId || !event) return\n      if (event.type === 'user/message') {\n        const data = event.data || {}\n        const kind = data.source && data.source.kind\n        // 通知 / relay / job / 时间快照都不是人说的；无 source 的老宿主按人话处理（与 lastUserText 同口径）。\n        if (kind && kind !== 'user') return\n        const text = textOf({ content: data.content })\n        if (text.trim()) sessions.humanText.set(sessionId, text.trim())\n        return\n      }\n      if (event.type !== 'tool/call') return\n      const data = event.data || {}\n      const calls = sessions.observed.ensure(sessionId)\n      calls.push({ name: String(data.name || ''), arguments: String(data.arguments || '') })\n      if (calls.length > OBSERVED_CALLS_MAX) calls.shift()\n    } catch {\n      // 观察失败绝不影响宿主请求\n    }\n  })\n}\n\n/** 注册 agent/pre-step 监听，向每步请求的 enter 决策追加记忆消息（默认开）。\n * 宿主瀑布事件签名为 (payload, next)：payload.agent.session 提供会话（header.cwd=项目根）。\n * 任何异常/无会话 cwd → 原样返回默认决策，零副作用，绝不让宿主请求受影响。\n */\nexport function installAutoInject(ctx, config) {\n  const auto = (config && config.autoContext) || {}\n  if (auto.enabled === false) return\n  const cfg = cfgEngine(config)\n  // 审计配置同 cfg：安装时解析一次（与 autoContext 其余开关一致）。\n  const audit = cfgAudit(config)\n  const shadow = cfgShadow(config)\n  const sessions = new InjectionSessions()\n\n  installCallObserver(ctx, sessions)\n  if (typeof ctx.effect === 'function') {\n    ctx.effect(() => () => sessions.clear())\n  }\n  ctx.on('agent/pre-step', async (payload, next) => {\n    // 宿主契约是 waterfall(payload, next)，next 一定存在；但一旦宿主版本漂移、或事件被当\n    // 普通事件调用，next 缺失会让本监听器 reject（历史事故正是 `next is not a function`）。\n    // 更致命的是返回 undefined：宿主 agent.ts 直接读 `decision.kind`，会崩掉整步 → 无法回复。\n    // 因此两种情况都退化为一个合法的 enter 决策，绝不让宿主请求受影响。\n    const fallback = () => ({ kind: 'enter', messages: (payload && payload.messages) || [] })\n    const decision = typeof next === 'function' ? await next() : fallback()\n    if (!decision) return fallback()\n    if (decision.kind !== 'enter') return decision\n    try {\n      return (await injectForStep({ payload, decision, config, cfg, audit, shadow, sessions })) || decision\n    } catch (err) {\n      console.error(`[dsh-project-memory] auto-inject skipped: ${err?.message || err}`)\n      return decision\n    }\n  })\n}\n\n/** 已就「会话根不安全」提示过的目录：每个进程、每个根只提示一次。 */\nconst warnedUnsafeRoots = new Set()\n\nfunction warnUnsafeSessionRoot(root, rejection) {\n  if (warnedUnsafeRoots.has(root)) return\n  warnedUnsafeRoots.add(root)\n  const field = rejection?.field ? `; adjust \\`${rejection.field}\\` under \\`- id: project-memory\\` if this is intentional` : ''\n  console.error(\n    `[dsh-project-memory] session cwd ${root} is not a project root (${rejection?.reason || 'home / system / package-manager prefix'}${field}); ` +\n      'project memory and its audit logs are disabled for this session. Start dsh inside a project directory to enable them.',\n  )\n}\n\n/**\n * 一个 pre-step 的注入决策：解析会话 → 排程 → 必要时构造消息。\n * 返回 null 表示本步无事可做（交回原决策）。\n */\nasync function injectForStep({ payload, decision, config, cfg, audit, shadow, sessions }) {\n  const session = payload && payload.agent && payload.agent.session\n  // 与工具侧同一口径的「当前工作目录」：0.2.1+ 走 workingDirectory 投影（cd 后会变），\n  // 老宿主回退 header.cwd。少了这一步，cd 之后审计与懒索引会落在两个不同的 store 里。\n  const cwd = sessionWorkingDir(session, { agent: payload?.agent })\n  const sessionId = session && session.id\n  if (!cwd || !sessionId) return null\n  // 会话 cwd 命中内置名单 / roots.deny / roots.exclude 时整条链路停在这里：不读 store\n  // （历史遗留的超大 store 光是 load() 就能 OOM），也不写审计——`appendShadowAudit` 里的\n  // mkdirSync 正是把 `.dsh-project-memory` 造进家目录、进而触发\"目录自标记 → 家目录被锁成项目\"的那一步。\n  const rejection = rootRejection(cwd, config)\n  if (rejection) {\n    warnUnsafeSessionRoot(cwd, rejection)\n    return null\n  }\n  // 记忆根与懒索引/工具侧同一套解析：项目标记优先，其次是安全的会话工作目录。\n  // 少了这一步，同一个会话的审计日志与懒索引会落在两个不同的 store 里。\n  const root = resolveProjectMemoryRoot(cwd, config)\n  if (!root) return null\n\n  // 意图是**会话状态**：先看本步 delta 里有没有新的人类消息，没有则回退到本会话最后一条。\n  // `agent/pre-step` 拿到的是 claimed delta（宿主 agent-loop 的 inbox.claim），会话中段通常\n  // 只有 tool result / 子代理报告 / job 通知，拿它们当查询就是\"这步在做什么\"用错了来源。\n  const deltaHuman = lastUserText(decision.messages)\n  const rememberedHuman = sessions.humanText.peek(sessionId) || ''\n  const query = deltaHuman || rememberedHuman\n  const querySource = deltaHuman ? 'delta' : rememberedHuman ? 'session' : 'none'\n  const memoryRoot = memoryRootFor(root, config.memoryDir)\n  const store = new ProjectMemoryStore(memoryRoot).load()\n  const globalStore = new GlobalStore(cfg.globalFile || defaultGlobalFile()).load()\n  const boundTaskId = store.getBoundTaskId(sessionId)\n  const task = boundTaskId ? store.getTask(boundTaskId) : null\n\n  // 两个窗口合并进同一个就绪上下文：人类消息（先发）+ 已观察动作（反应）。\n  // 动作平面（S1）：**只**从结构化 tool/call 归一（activityFromCalls），不再把全部参数拼成\n  // actionText —— 那会把 subagent 提示词 / remember 正文 / 任意脚本里的词当成动作（实测 8 步）。\n  const observed = sessions.observed.ensure(sessionId)\n  const activity = activityFromCalls(observed)\n  const readiness = buildReadinessContext({\n    humanText: query || '',\n    ops: activity.ops,\n    targets: activity.targets,\n    hosts: activity.hosts,\n  })\n\n  const stepNo = sessions.step.ensure(sessionId) + 1\n  sessions.step.set(sessionId, stepNo)\n  const quota = sessions.quota.ensure(sessionId)\n  const silence = sessionSilence({ cfg, quota, stepNo })\n  // 条目级去重：本会话已注入过、且正文未变的条目不再参与排程（正文被编辑过 → 立刻允许重发）。\n  const skipItem = makeSkipItem(sessions.items.ensure(sessionId), stepNo, cfg.reinjectItemsAfter || 0)\n\n  const built = buildInjection({\n    query: query || '',\n    readiness,\n    task,\n    store,\n    globalStore,\n    projectTagsList: projectTags(root),\n    cfg,\n    skipItem,\n    skipItems: silence.reason !== null,\n    silenceReason: silence.reason || 'cooldown',\n    maxItems: silence.itemsLeft,\n    maxChars: silence.charsLeft,\n    // 可选向量层：没装/没配就是 null → 提示通道与纯词法逐字段一致（闸门、注入条数都不变，\n    // 只有层内排序会用到余弦）。构造失败也在 createVectorRerank 内部吞掉并返回 null。\n    rerank: await createVectorRerank({\n      storeDir: memoryRoot,\n      items: vectorItemsFrom(store, globalStore),\n      vectorDir: cfg.vectorDir,\n      alpha: cfg.vectorAlpha,\n      // 两个实验性旋钮：不配就是 undefined → 对应的闸门整段不执行（默认路径与旧版一致）\n      itemMin: cfg.vectorItemMin,\n      speakMin: cfg.vectorSpeakMin,\n    }),\n  })\n\n  // 未注入 ≠ 无事发生：因预算被挤掉的条目按 cfg.budgetLog 留痕（默认 off，见 cfgEngine）。\n  // 留痕仍然记账（去重 + 上限），只是默认不外泄到用户的终端。\n  recordDropped({ sessions, sessionId, dropped: built.dropped, budgetLog: cfg.budgetLog })\n\n  // 影子记录：**每步**都写一行（含零注入的静默步与对照组），带全部候选的判据特征。\n  // 主审计只在真的注入时写，静默步零痕迹 → 日志无法离线重放\"换个阈值会怎样\"，\n  // 也攒不出训练样本。只写盘、不进 prompt、不花 token。\n  appendShadowAudit(memoryRoot, shadowRecordFrom({\n    sessionId,\n    root,\n    step: stepNo,\n    query: query || '',\n    querySource,\n    ops: readiness.ops,\n    opsIntent: readiness.intentOps,\n    writes: readiness.targets,\n    reasons: built.reasons,\n    candidates: built.candidates,\n    scoreQuery: built.scoreQuery,\n    dropped: built.dropped,\n    silence: silence.reason,\n  }), shadow, root)\n\n  // 记忆根通告：根是**推定**的（会话工作目录，且该目录没有任何项目标记）时，\n  // 第一次注入前告诉模型\"记忆现在存在哪、怎么改\"。它是状态声明（与常驻任务卡同类），\n  // 只发一次、不占条目额度；否则模型只看到一条来自某处的记忆，却不知道那个根是怎么来的。\n  const notice = rootNotice({ root, sessionId, sessions, config })\n\n  const fp = built.text ? fingerprint(built.dedupeText ?? built.text) : fingerprint(notice || '')\n  const injectedText = notice ? (built.text ? `${notice}\\n${built.text}` : notice) : built.text\n  if (!injectedText || fp === sessions.lastText.peek(sessionId)) return null\n  sessions.lastText.set(sessionId, fp)\n  const itemCount = built.reasons.length\n  const summary = itemCount\n    ? `memory inject: ${itemCount} item(s)${built.entry ? ' + task card' : ''}`\n    : built.entry ? 'memory inject: task card' : 'memory root notice'\n\n  // 只记真的进了上下文的那几条：dropped 的没被看到，不能记账（否则以后永远不再注入）。\n  const seen = sessions.items.ensure(sessionId)\n  for (const r of built.reasons) {\n    if (r && r.id && r.hash) seen.set(r.id, { hash: r.hash, step: stepNo })\n  }\n  // 会话额度只被\"条目\"消耗；任务卡不算（否则任务一多就把记忆挤没了）。\n  if (built.reasons.length) {\n    quota.items += built.reasons.length\n    quota.chars += typeof built.itemChars === 'number' ? built.itemChars : 0\n    quota.lastStep = stepNo\n  }\n\n  // 使用记账：注入进上下文 = 这条记忆被用到了。必须在这里显式落盘——注入路径不会走到\n  // 任何其它 save()，只标脏等于进程退出就丢。记账失败绝不影响注入（与审计同约定）。\n  if (built.reasons.length) {\n    try {\n      if (recordHit({ store, globalStore, ids: built.reasons.map((r) => r.id) })) {\n        // 只有这个根里真有东西才落盘。否则一次**全局** insight 的命中就会为一个从没被\n        // 索引过的容器目录建出整个 store（`save()` 会 mkdir）。审计侧同样不建，见 audit.js。\n        if (store.hasContent) store.save()\n        globalStore.commit()\n      }\n    } catch {\n      /* ignore：记账是旁路，不能拖累注入 */\n    }\n  }\n\n  // S0 观测：只记真的进了上下文的那一次（dropped 单独出现不写，否则每步刷屏）。\n  appendInjectionAudit(memoryRoot, auditRecordFrom({\n    sessionId,\n    root,\n    step: stepNo,\n    text: injectedText,\n    labels: built.labels,\n    reasons: built.reasons,\n    dropped: built.dropped,\n    budget: { items: quota.items, chars: quota.chars, lastStep: Number.isFinite(quota.lastStep) ? quota.lastStep : null },\n    silence: silence.reason,\n  }), audit, root)\n\n  return { ...decision, messages: [...decision.messages, injectionMessage(injectedText, summary)] }\n}\n\n/**\n * 「记忆根是推定的」一次性通告。\n *\n * 触发条件：根是**安全目录但自身没有任何项目标记**（即根来自会话工作目录，而不是\n * `.git`/`package.json` 这类声明）。此时插件会按 cwd 建 `.dsh-project-memory`——必须\n * 让模型知道这件事，否则它只会看到记忆来自一个自己没指定过的位置，而纠正的成本随\n * 会话推进快速上升。通告只发一次，且与常驻任务卡同类：是状态声明，不占条目额度。\n *\n * 关掉它：`autoContext.rootNotice: false`。\n */\nfunction rootNotice({ root, sessionId, sessions, config }) {\n  if (config?.autoContext?.rootNotice === false) return null\n  if (sessions.rootNoticed.peek(sessionId)) return null\n  if (hasProjectMarker(root)) return null\n  sessions.rootNoticed.set(sessionId, true)\n  return (\n    `memory root: ${root} (inferred from the session working directory; no project marker found). ` +\n    'If project memory should live elsewhere, pass `root: <dir>` to index_repo / watch_repo / remember / query_memory, ' +\n    'or restart dsh inside the project directory.'\n  )\n}\n\n/**\n * 会话级限流（S3）：冷却步数 / 条目条数 / 条目字符。三个任一触顶 → 条目通道整体沉默，\n * 但本轮\"本该注入什么\"仍会进 dropped（不做静默降级）。\n */\nfunction sessionSilence({ cfg, quota, stepNo }) {\n  const cooling = Number.isFinite(quota.lastStep) && stepNo - quota.lastStep < cfg.gateCooldownSteps\n  const itemsLeft = Math.max(0, cfg.maxItemsPerSession - quota.items)\n  const charsLeft = Math.max(0, cfg.maxItemCharsPerSession - quota.chars)\n  const reason = cooling ? 'cooldown'\n    : itemsLeft === 0 ? 'session-items'\n      : charsLeft === 0 ? 'session-chars' : null\n  return { reason, itemsLeft, charsLeft }\n}\n\n/** 条目级去重判据：会话里注入过且正文未变 → 跳过。cooldown=0 永久有效，>0 走步数冷却。 */\nfunction makeSkipItem(seen, stepNo, cooldown) {\n  return (it) => {\n    const rec = seen.get(it.id)\n    if (!rec || rec.hash !== insightItemHash(it)) return false\n    return cooldown === 0 || stepNo - rec.step < cooldown\n  }\n}\n\n/** 预算丢弃的留痕（cfg.budgetLog）：once=每会话首次，all=丢弃组合每变一次。 */\nfunction recordDropped({ sessions, sessionId, dropped, budgetLog }) {\n  if (!dropped || !dropped.length || budgetLog === 'off') return\n  const signature = dropped.map((d) => `${d.id}:${d.reason}`).join(',')\n  const previous = sessions.lastDropped.peek(sessionId)\n  if (previous === signature) return\n  sessions.lastDropped.set(sessionId, signature)\n  if (budgetLog === 'all' || previous === undefined) {\n    console.error(\n      `[dsh-project-memory] auto-inject degraded: ${dropped.length} insight(s) kept out by budget — `\n      + dropped.map((d) => `${d.id}(${d.reason})`).join(', '),\n    )\n  }\n}\n\n/** 追加的注入消息：必须是带 source 的完整消息——裸 {role,content} 会让宿主读 message.source 时崩。 */\nfunction injectionMessage(text, summary) {\n  return createUserMessage({\n    content: [{ type: 'text', text: `\\n\\n${INJECT_MARK} ${PLUGIN_NAME} · auto-context\\n${text}` }],\n    // 宿主对第三方生产者的 `snapshot` 只做追加，不会用后一条替换前一条（只有它自己的\n    // runtime-context 走 surfaceOp replace）。所以这里声明 `notice`：它如实表示“这一步注入了\n    // 什么”，不会让 UI 打出“取代先前快照”的空头承诺。summary 是 UI 收起时的一行说明。\n    source: {\n      kind: SOURCE_KIND,\n      form: 'notice',\n      summary,\n    },\n  })\n}"
    },
    {
      "path": "src/store.js",
      "content": "import { createHash } from 'node:crypto'\nimport { mkdirSync, readFileSync, readdirSync, renameSync, rmSync, statSync, unlinkSync, writeFileSync } from 'node:fs'\nimport path from 'node:path'\nimport { tokenizeRaw, makeSearchText } from './util/search.js'\nimport { acquireDirLock, writeJsonAtomic } from './util/fs.js'\nimport { debugPersistence } from './util/persist.js'\nimport { trackDirty, untrackDirty } from './util/flush.js'\nimport { backfillDerivedTriggers } from './readiness.js'\n\nconst FORMAT_FILE = 'format.json'\nconst INDEX_FILE = 'index.json'\nconst ENTRIES_FILE = 'entries.json'\nconst EXPERIENCE_FILE = 'experience.json'\nconst TASKS_FILE = 'tasks.json'\nconst BINDING_FILE = 'binding.json'\nconst WATCH_FILE = 'watch.json'\nconst INSIGHTS_FILE = 'insights.json'\nconst SHARDS_DIR = 'shards'\nconst GITIGNORE_FILE = '.gitignore'\n/** ≤0.5.10 的 TS 增强结果缓存目录；0.5.11 起废弃并自愈清理。 */\nconst LEGACY_TYPE_CACHE_DIR = 'type-cache'\n\nconst storeCache = new Map()\n/** 单实例超预算的告警只打一次（key = 解析后的 store 目录）。 */\nconst warnedOverBudget = new Set()\n/** 条目数上限（兜底）。 */\nconst STORE_CACHE_MAX = 32\n/**\n * 驻留内存的估算上限。只数\"几个 store\"是不够的：单个大仓库 store 实测驻留\n * 68MB（`load()` 后）～110MB（物化 `searchText` + 建 IDF/符号索引后），\n * 语料是 deepseek-harness / 70119 条目。32 个就是几 GB。\n * 估算口径见 `_estimateResidentBytes`（对内存里的对象图精确计数，不再用读盘文本量换算）。\n */\nlet STORE_CACHE_MAX_BYTES = 256 * 1024 * 1024\n/** 每轮 save 最多补写多少个待压实的老分片（有界，避免升级后一次重写整库）。 */\nconst COMPACT_BATCH = 200\n\n/**\n * 一个值的驻留字节：形状开销 + 字符串的**编码字节数**。\n *\n * 用 `Buffer.byteLength()` 而不是 `String.length`：CJK 在 UTF-8 里 3 字节/字符，而 V8\n * 双字节串 2 字节/字符——UTF-8 对非 ASCII 是偏高的代理指标，对纯 ASCII 精确。缓存预算\n * 容得下这个误差（实测两端 ±13%，见 `test/store-cache.test.mjs` 与内部设计笔记）。\n *\n * 递归用深度上限而不是 `Set` 去环：store 的对象图来自 `JSON.parse`，本就无环；深度上限\n * 既挡畸形数据，又比逐对象 `Set` 查重快 ~30%（70119 条目实测 36ms vs 52ms）。\n */\nconst RESIDENT_OBJ_BYTES = 60\nconst RESIDENT_ARR_BYTES = 40\nconst RESIDENT_KEY_BYTES = 40\nconst RESIDENT_STR_BYTES = 16\nconst RESIDENT_MAX_DEPTH = 8\n\n/**\n * 精确计量的版本戳：entries 的构成 + `searchText` 的物化状态 + 辅助集合的内容各算一维。\n * 三维缺一不可——漏掉哪一维，估算就停在那一维变更前的水位。\n */\nfunction residentStampOf(store) {\n  return `${store._entriesVersion}:${store._materializeVersion}:${store._auxVersion}`\n}\n\n/**\n * 精确计量的**触发上界**（不是估算本身）：内存里文本字符数 × 4 + 骨架常数。\n *\n * 为什么必须有它：精确计量要遍历全库字符串（`Buffer.byteLength` 逐串编码），12.6k 文件 /\n * 80k 条目实测 ~40ms。放在每次冷加载的热路径上，就是白花这笔钱去判断\"要不要逐出\"——\n * 而绝大多数加载离 256MB 预算差得远，逐出根本不可能发生。\n *\n * 系数取偏保守：宁可多走一次精确计量，也不能把预算算松。ASCII 下 1 字符 ≈ 1 字节驻留\n * 外加键与对象形状开销（符号条目实测 ~4×）；CJK 字符驻留 2 字节，而 UTF-8 文本里 3 字节，\n * 字符数只会更少。精确数一旦算过且版本未变，直接用它，不必再估。\n *\n * 两条腿合成一个数：\n *  - `_textChars`：entries 的文本量，由三条路径维护（读盘分片 / 写条目 / 物化 `searchText`），\n *    按文件**替换式**累计，所以重写同一个文件不会把它算两遍；\n *  - `auxCharsOf()`：辅助集合（experience / insights / tasks / binding / watch）的文本量。\n *    它们不在分片文本里，`load()` 之后还会被写大，单列一条腿才不会漏。\n * 在真实语料上标定的上界 / 精确值比是 1.16~1.74 倍。\n */\nconst RESIDENT_BOUND_PER_CHAR = 4\nconst RESIDENT_SKELETON_BYTES = 1024\n\nfunction residentBoundBytes(store) {\n  const stamp = residentStampOf(store)\n  if (store._residentStamp === stamp) return store._residentBytes\n  return RESIDENT_SKELETON_BYTES + (store._textChars + auxCharsOf(store)) * RESIDENT_BOUND_PER_CHAR\n}\n\n/**\n * 写路径的文本量估计（只用于上界）：`searchText` + 不在它里面的字段 + 每条的键/JSON 开销。\n * 不重复计 title / keywords / summary / terms / sourcePath —— 它们都已经在 `searchText` 里。\n */\nfunction entryTextChars(entries) {\n  let sum = 0\n  for (const entry of entries) {\n    sum += 160\n    sum += (entry.searchText || '').length\n    sum += (entry.text || '').length\n    sum += (entry.id || '').length + (entry.relPath || '').length\n  }\n  return sum\n}\n\n/** 仅供测试与标定：上界口径（必须 ≥ `_estimateResidentBytes`，否则字节预算会被算松）。 */\nexport function _residentBoundBytesForTest(store) {\n  return residentBoundBytes(store)\n}\n\n/**\n * 驻留量的对象图遍历。精确口径与上界口径**共用这一份**——抄成两份迟早会漂。\n *\n * `charsOnly` 决定字符串怎么记：精确口径走 `Buffer.byteLength`（真字节数）；上界口径只取\n * `length` 字符数，省掉编码这一步。它是安全的上界：`RESIDENT_BOUND_PER_CHAR = 4` 保证 ×4 后\n * 仍 ≥ 真字节数（UTF-8 里一个 UTF-16 码元最多 3 字节，代理对 2 码元 / 4 字节）。\n */\nfunction residentSizeOf(value, charsOnly, depth = 0) {\n  if (depth > RESIDENT_MAX_DEPTH) return 0\n  const type = typeof value\n  if (type === 'string') return RESIDENT_STR_BYTES + (charsOnly ? value.length : Buffer.byteLength(value))\n  if (type === 'number' || type === 'bigint') return 16\n  if (type === 'boolean' || value === null) return 8\n  if (Array.isArray(value)) {\n    let sum = RESIDENT_ARR_BYTES\n    for (const item of value) sum += 8 + residentSizeOf(item, charsOnly, depth + 1)\n    return sum\n  }\n  if (type === 'object') {\n    let sum = RESIDENT_OBJ_BYTES\n    for (const key in value) sum += RESIDENT_KEY_BYTES + residentSizeOf(value[key], charsOnly, depth + 1)\n    return sum\n  }\n  return 0\n}\n\n/** 精确口径：内存里留下的对象图，按真字节数（`_estimateResidentBytes` 用）。 */\nfunction residentBytesOf(value) {\n  return residentSizeOf(value, false, 0)\n}\n\n/**\n * 上界口径：只数字符（`auxCharsOf` 用）。给辅助集合单开这条路是因为它们条目数小（经验 / 任务\n * 都有上限），逐节点求和的代价可以忽略；entries 有几万条，那条路继续走增量记账的 `_textChars`。\n */\nfunction residentCharsOf(value) {\n  return residentSizeOf(value, true, 0)\n}\n\n/**\n * 辅助集合的文本量（上界口径），按 `_auxVersion` 记忆化。\n *\n * 为什么单列：`_textChars` 只跟 entries；这几个集合在 `load()` 之后还会被写大，不进上界就会在\n * 缓存其实已超预算时跳过精确计量与逐出（实测单 store 上界 1024 B、实际 19.08 MB）。\n * 记忆化是必须的——`evictStoreCache` 对整个缓存逐 store 求和，不记忆化就是每次冷加载重算一遍。\n */\nfunction auxCharsOf(store) {\n  if (store._auxStamp === store._auxVersion) return store._auxChars\n  store._auxChars =\n    residentCharsOf(store.insights) +\n    residentCharsOf(store.tasks) +\n    residentCharsOf(store.binding) +\n    residentCharsOf(store.watchlist)\n  store._auxStamp = store._auxVersion\n  return store._auxChars\n}\n\n/**\n * 单个 store 的驻留估算：数**内存里留下的对象图**，按版本记忆化。\n *\n * 为什么不是\"读盘文本量换算\"（旧实现）：那个口径有两个错。\n *  1. 时序错位——它量的是 `load()` 读进来的 JSON 文本，而 `searchText` 要到\n *     `allEntries()` 才物化，同一份数据在物化前后估出两个数（实测 76MB → 107MB）。\n *  2. 账不对物——旧分片里还带着 `searchText` / `linkedSymbols`，`load()` 会\n *     `stripPersistedDerived` 把它们删掉，可文本量已经把被删的字节算进去了。\n *     实测一个 12.6k 文件的父目录 store：读盘 212.6MB，真实驻留 101.7MB。\n *\n * 两个版本键都参与失效：`_entriesVersion`（`setEntries` / `removeFile` / `_loadSharded`）\n * 与 `_materializeVersion`（`allEntries()` 物化 `searchText`）。漏掉后者就是旧实现的错。\n *\n * 代价：版本变化后的**一次**全量遍历（70119 条目 ~40ms）。必须记忆化——`evictStoreCache`\n * 是对**整个缓存**逐 store 求和的，不记忆化等于每次冷加载都把缓存里所有 store 重数一遍。\n */\nexport function _estimateResidentBytes(store) {\n  const stamp = residentStampOf(store)\n  if (store._residentStamp !== stamp) {\n    store._residentBytes =\n      residentBytesOf(store.entries) +\n      residentBytesOf(store.files) +\n      residentBytesOf(store.tasks) +\n      residentBytesOf(store.insights) +\n      residentBytesOf(store.watchlist) +\n      residentBytesOf(store.binding)\n    store._residentStamp = stamp\n  }\n  return store._residentBytes\n}\n\n/** 按 LRU 逐出，直到同时满足条数与字节预算；刚加入的 keepKey 即使超预算也保留。 */\nfunction evictStoreCache(keepKey) {\n  // 只在**真有可能逐出**时才付精确计量的钱：条数超上限，或保守上界就已超字节预算。\n  // 宽裕时（单项目常态）一次对象图遍历都不做——冷加载因此不背那次全库扫描。\n  let exact = storeCache.size > STORE_CACHE_MAX\n  if (!exact) {\n    let bound = 0\n    for (const store of storeCache.values()) bound += residentBoundBytes(store)\n    exact = bound > STORE_CACHE_MAX_BYTES\n  }\n  let total = 0\n  if (exact) for (const store of storeCache.values()) total += _estimateResidentBytes(store)\n  while (storeCache.size > STORE_CACHE_MAX || (exact && total > STORE_CACHE_MAX_BYTES)) {\n    const oldest = storeCache.keys().next().value\n    if (oldest === undefined || oldest === keepKey) break\n    if (exact) total -= _estimateResidentBytes(storeCache.get(oldest))\n    // 逐出前先落盘：任务热点/人类消息是延迟写的（turn/end 才 flush），\n    // 若这里直接丢实例，还没到回合结束的变更就再也回不来了。save() 无脏数据时自己早退。\n    const evicted = storeCache.get(oldest)\n    if (evicted && evicted.hasDirty()) {\n      try {\n        evicted.save()\n      } catch (err) {\n        console.error(`[dsh-project-memory] evicted store save failed: ${err?.message || err}`)\n      }\n    }\n    storeCache.delete(oldest)\n  }\n  // 没做过精确计量就不报\"单实例超预算\"：算都没算，报出来的数是估的。真超预算时\n  // （多一个 store 就会触发上界）下一次加载会走到这里并如实告警。\n  if (!exact) return\n  // keepKey 豁免是**有意**的：刚加载的 store 必须立刻可用。但它的代价是\"单实例超预算时\n  // 预算不再是上界\"——这个代价不能是隐式的，所以每个这样的 store 告警一次（每 root 一次）。\n  const kept = _estimateResidentBytes(storeCache.get(keepKey))\n  if (kept > STORE_CACHE_MAX_BYTES && !warnedOverBudget.has(keepKey)) {\n    warnedOverBudget.add(keepKey)\n    console.error(\n      `[dsh-project-memory] store ${keepKey} 单实例驻留约 ${Math.round(kept / 1048576)}MB，` +\n        `超过 storeCache 预算 ${Math.round(STORE_CACHE_MAX_BYTES / 1048576)}MB；` +\n        '刚加载的 store 不逐出（有意豁免），多 root 场景下其他 store 会被更频繁地逐出。',\n    )\n  }\n}\n\n/** 仅供测试：临时收窄字节预算（返回恢复函数），免得测试真去分配 256MB 字符串。 */\nexport function _setStoreCacheBudgetForTest(bytes) {\n  const previous = STORE_CACHE_MAX_BYTES\n  STORE_CACHE_MAX_BYTES = bytes\n  return () => {\n    STORE_CACHE_MAX_BYTES = previous\n  }\n}\n\n/** 仅供测试：当前缓存 key 的 LRU 顺序（最旧在前）。 */\nexport function _storeCacheKeysForTest() {\n  return [...storeCache.keys()]\n}\n\n/** 已就\"无法迁移的旧 store\"告警过的目录：避免每次 load() 都刷一行。 */\nconst migrationWarned = new Set()\n\n/** 纯对象判定（排除 null / 数组）：磁盘读入的 JSON 形状校验统一走它。 */\nfunction isRecord(value) {\n  return Boolean(value) && typeof value === 'object' && !Array.isArray(value)\n}\n\n/** 两个 ISO 时间戳的先后；缺失/非法一律 0，保证可比较。 */\nfunction newerIso(a, b) {\n  const ta = Date.parse(a || '') || 0\n  const tb = Date.parse(b || '') || 0\n  return ta - tb\n}\n\n/**\n * 落盘的 entry 只保留**不可推导的事实**。两个派生字段永远不写盘：\n *  - `linkedSymbols`：跨实体派生（取决于符号表当前状态），读取期由 src/link.js 解算；\n *  - `searchText`：自派生（只依赖本 entry），由 `allEntries()` 在内存里物化。\n * 旧 store 里的这两个字段在加载时剥掉，于是下一次写盘自然压实。\n * 实测两者在一个真实大仓库 store 里合计约 245MB（链接 222.8MB + searchText 22.7MB）。\n */\nconst PERSISTED_DERIVED = ['linkedSymbols', 'searchText', 'typeSig']\nconst PERSISTED_DERIVED_SET = new Set(PERSISTED_DERIVED)\n\n/** 有没有派生字段要剥。没有就走零分配路径（绝大多数条目、以及所有新写的分片）。 */\nfunction hasPersistedDerived(entry) {\n  for (const key of PERSISTED_DERIVED) if (key in entry) return true\n  return false\n}\n\n/**\n * 按**非派生键重建**一个对象。\n *\n * 不用 `delete`：删除属性会把 entry 推进 V8 的字典模式，之后每个属性都变成哈希表项。\n * 本仓库真实条目形状实测 —— `delete` 后 **1196 B/条**，重建后 **436 B/条**（20k 条 / --expose-gc）。\n * 加载路径上这是常驻内存（`storeCache` 里所有 store 都算），写盘路径上同款浪费。\n *\n * `undefined` 值的键也不复制：`typeSig: undefined` 是 enhancer 的实现细节（见 src/enhancer.js），\n * JSON 里本来就不存在，留在内存对象里只会占一个属性槽。\n */\nfunction rebuildWithoutDerived(entry) {\n  const out = {}\n  for (const key of Object.keys(entry)) {\n    if (PERSISTED_DERIVED_SET.has(key)) continue\n    const value = entry[key]\n    if (value === undefined) continue\n    // JSON.parse 可以把 `__proto__` 变成自有属性，而 `out[key] = value` 会走去改原型 —— 显式定义。\n    if (key === '__proto__') Object.defineProperty(out, key, { value, enumerable: true, writable: true, configurable: true })\n    else out[key] = value\n  }\n  return out\n}\n\n/**\n * 剥掉派生字段（加载路径用）。没有派生字段时**原对象返回**（零分配热路径）。\n * @returns {object} 不含派生字段的条目（可能是同一个对象）\n */\nfunction stripPersistedDerived(entry) {\n  if (!entry || typeof entry !== 'object') return entry\n  if (!hasPersistedDerived(entry)) return entry\n  return rebuildWithoutDerived(entry)\n}\n\n/**\n * 返回不含派生字段的条目（写盘路径用，不能动内存里的对象）。\n * 同样重建而不是 spread+delete —— 两个路径的字典模式代价是一样的。\n */\nfunction withoutPersistedDerived(entry) {\n  if (!entry || typeof entry !== 'object') return entry\n  if (!hasPersistedDerived(entry)) return entry\n  return rebuildWithoutDerived(entry)\n}\n\n/** 仅供测试：加载/写盘路径的剥离实现（内存形状由测试用 --expose-gc 度量）。 */\nexport function _stripPersistedDerivedForTest(entry) {\n  return stripPersistedDerived(entry)\n}\n\nfunction loadJson(filePath, fallback, counter) {\n  let raw\n  try {\n    raw = readFileSync(filePath, 'utf8')\n  } catch {\n    return fallback\n  }\n  // 可选：累计读盘文本的字符数。只用于 `residentBoundBytes`（要不要做精确计量的上界），\n  // 不参与精确估算本身——后者数的是内存里的对象图。\n  if (counter) counter.chars += raw.length\n  try {\n    return JSON.parse(raw)\n  } catch {\n    const backup = `${filePath}.${Date.now()}.corrupt`\n    try {\n      renameSync(filePath, backup)\n      console.error(`[dsh-project-memory] corrupted ${path.basename(filePath)} moved to ${path.basename(backup)}; starting fresh`)\n    } catch (err) {\n      console.error(`[dsh-project-memory] corrupted ${path.basename(filePath)} could not be backed up: ${err.message}`)\n    }\n    return fallback\n  }\n}\n\nfunction shardRelPath(dir, rel) {\n  return path.join(dir, SHARDS_DIR, createHash('sha256').update(rel).digest('hex') + '.json')\n}\n\nexport class ProjectMemoryStore {\n  constructor(memoryDir) {\n    this.dir = memoryDir\n    this.files = {}\n    this.entries = {}\n    this.experience = []\n    this.insights = { version: 1, migratedAt: null, items: [] }\n    this.tasks = []\n    this.binding = {}\n    this.watchlist = []\n    this._dirtyShards = new Set()\n    this._removedShards = new Set()\n    /** 加载时的分片 hash：跨进程写冲突检测的基准。 */\n    this._baseFileSha = new Map()\n    /** 本地删除留痕：合并另一进程的磁盘状态时不能把它们复活。 */\n    this._deletedInsightIds = new Set()\n    this._deletedTaskIds = new Set()\n    this._deletedBindings = new Set()\n    this._removedWatch = new Set()\n    /** 上次落盘/加载时的 insight id 集合：原地 splice 的删除也要能被合并逻辑看见。 */\n    this._baseInsightIds = new Set()\n    /**\n     * 本进程**新建**的条目。合并另一进程的磁盘状态时，\"磁盘没有但内存有\"有两种可能：\n     * 我新建的（要补写）或**对方删了**（不能写回）。没有这个集合，后者就会被复活\n     * （实测：B 真删、A 下一次注入记账触发 save，已删条目重新出现在磁盘上）。\n     */\n    this._createdInsightIds = new Set()\n    this._createdTaskIds = new Set()\n    /** 上一次 save 是否真的落到盘上（锁竞争/权限失败时为 false）。 */\n    this.lastSaveOk = true\n    /** `shards/` 的 `.tmp` 清扫节流：NTFS 上 readdir(数千分片) 不便宜，不能每次 save 都扫。 */\n    this._lastShardTmpSweep = 0\n    /** 自我忽略文件已确认存在：省掉每次 save 的 existsSync（Windows 上每次都要过一次过滤驱动）。 */\n    this._selfIgnoreReady = false\n    /** store 目录 / shards 目录已确认存在：首次写之后不再每次 save 都 mkdir（9p 上每次 ~4ms）。 */\n    this._storeDirReady = false\n    this._shardsDirReady = false\n    this._lockWarned = false\n    this._conflictWarned = new Set()\n    /** 锁竞争跳过落盘后的有限次延迟重试；unref，避免拖住进程退出。 */\n    this._saveRetryTimer = null\n    this._saveRetryAttempts = 0\n    this._dirtyInsights = false\n    this._dirtyTasks = false\n    this._dirtyBinding = false\n    this._dirtyWatch = false\n    this._formatWritten = false\n    this._idfCache = null\n    /** entries 的变更计数：IDF 缓存与符号索引（读取期链接）都据此失效。 */\n    this._entriesVersion = 0\n    /** 待压实的老分片（≤0.5.10 落盘时带 linkedSymbols/searchText）；save() 每轮有界补写。 */\n    this._compactQueue = new Set()\n    /** 驻留字节估算的记忆化结果与版本戳（见 `_estimateResidentBytes`）。 */\n    this._residentBytes = 0\n    this._residentStamp = ''\n    /**\n     * entries 的文本字符数累计（读盘分片 + 写条目 + 物化 `searchText`），按文件**替换式**记。\n     * **只**用于 `residentBoundBytes` 判断\"要不要做精确计量\"；精确估算数的是对象图，不碰它。\n     */\n    this._textChars = 0\n    /** 每个文件当前的文本字符数，写入时按文件替换，避免重写同一文件被算两遍。 */\n    this._fileTextChars = new Map()\n    /**\n     * `searchText` 的物化计数。它和 `_entriesVersion` 一起构成驻留估算的失效键：\n     * 物化只改 entry 对象本身，不改 entries 的构成，所以不会 bump `_entriesVersion`。\n     */\n    this._materializeVersion = 0\n    /**\n     * 辅助集合（experience / insights / tasks / binding / watch）的内容版本：它们不在 entries\n     * 的记账面里，靠它让精确估算失效、并让 `auxCharsOf` 重算。每个改到它们的写口都要 bump。\n     */\n    this._auxVersion = 0\n    this._auxChars = 0\n    this._auxStamp = ''\n  }\n\n  load() {\n    const key = path.resolve(this.dir)\n    const hot = storeCache.get(key)\n    // 缓存命中即返回：`hot === this` 时再读一遍盘会静默丢弃本实例尚未 save() 的变更\n    // （_loadSharded/_loadInsights 会重新赋值 experience/tasks/insights…）。\n    if (hot) {\n      // LRU：命中挪到队尾，避免\"热的先被逐出、冷的常驻\"。\n      storeCache.delete(key)\n      storeCache.set(key, hot)\n      return hot\n    }\n    this._migrateLegacyIfNeeded()\n    this._loadSharded()\n    this._loadInsights()\n    this._pruneBindings()\n    this._removeLegacyTypeCache()\n    // 有些路径只读不写（审计 jsonl 直接写在 store 目录里），所以这里也补一次自我忽略，\n    // 让老版本建出来的 store 在第一次 load 就补上。\n    this.ensureSelfIgnore()\n    storeCache.set(key, this)\n    evictStoreCache(key)\n    return this\n  }\n\n  _migrateLegacyIfNeeded() {\n    const formatPath = path.join(this.dir, FORMAT_FILE)\n    if (loadJson(formatPath, null)?.version === 2) {\n      // 迁移在“写完标记、删旧文件前”崩溃会留下死文件；这里顺手清掉\n      for (const stale of [path.join(this.dir, ENTRIES_FILE), path.join(this.dir, INDEX_FILE)]) {\n        if (existsSafe(stale)) {\n          try {\n            unlinkSync(stale)\n            console.error(`[dsh-project-memory] removed leftover legacy file ${path.basename(stale)} after migration`)\n          } catch {\n            // locked or gone; will be retried next load\n          }\n        }\n      }\n      return\n    }\n    const legacyEntriesPath = path.join(this.dir, ENTRIES_FILE)\n    if (!existsSafe(legacyEntriesPath)) return\n    const legacyIndexPath = path.join(this.dir, INDEX_FILE)\n    // 先读两份旧文件：损坏的那份会在这里被 loadJson 备份为 .corrupt（保留现场）。\n    const index = loadJson(legacyIndexPath, null)\n    const entries = loadJson(legacyEntriesPath, null)\n    if (!isRecord(index) || !isRecord(entries)) {\n      const hasEntries = isRecord(entries) && Object.keys(entries).length > 0\n      if (!hasEntries) {\n        // entries 损坏（已备份）或本就是空的：没有可保护的数据，按空旧库收尾。\n        writeJsonAtomic(formatPath, { version: 2, layout: 'sharded' })\n        for (const stale of [legacyEntriesPath, legacyIndexPath]) {\n          try {\n            unlinkSync(stale)\n          } catch {\n            // already renamed away by corrupt backup, or gone; nothing to do\n          }\n        }\n        return\n      }\n      // index.json 是 entries.json → rel 的唯一映射。它缺失或损坏时继续迁移，会写出 0 个\n      // shard、打上 v2 标记、再把**完好的** entries.json 删掉——等于一次静默的数据清空。\n      // 保留现场，不写 format 标记，等 index.json 修好后再迁（每次进程只提示一次）。\n      if (!migrationWarned.has(this.dir)) {\n        migrationWarned.add(this.dir)\n        console.error(`[dsh-project-memory] legacy store at ${this.dir} has ${ENTRIES_FILE} but no readable ${INDEX_FILE}; migration skipped to protect it`)\n      }\n      return\n    }\n    const files = isRecord(index.files) ? index.files : {}\n    const orphans = Object.keys(entries).filter((rel) => !(rel in files))\n    if (orphans.length) {\n      console.error(\n        `[dsh-project-memory] migration dropped ${orphans.length} entry group(s) with no index record: ${orphans.slice(0, 3).join(', ')}${orphans.length > 3 ? ' …' : ''}`,\n      )\n    }\n    for (const rel of Object.keys(files)) {\n      // 父目录由 writeJsonAtomic 保证\n      writeJsonAtomic(shardRelPath(this.dir, rel), { relPath: rel, record: files[rel], entries: (entries[rel] || []).map(withoutPersistedDerived) })\n    }\n    writeJsonAtomic(formatPath, { version: 2, layout: 'sharded' })\n    for (const stale of [legacyEntriesPath, path.join(this.dir, INDEX_FILE)]) {\n      try {\n        unlinkSync(stale)\n      } catch {\n        // already renamed away by corrupt backup, or gone; nothing to do\n      }\n    }\n    console.error(`[dsh-project-memory] migrated legacy store at ${this.dir} to sharded layout (${Object.keys(files).length} files)`)\n  }\n\n  /**\n   * 读一个辅助集合文件（experience / tasks / insights / binding / watch）。\n   *\n   * 它们的文本量**不进** `_textChars`：那份账只跟 entries（按文件替换），辅助集合交给\n   * `auxCharsOf` 按对象图直接算——同一个集合由两个口径各记一半，迟早会漂。\n   */\n  _loadJson(filePath, fallback) {\n    return loadJson(filePath, fallback)\n  }\n\n  /** 按文件记文本量：替换而不是累加，重写同一个文件不会算两遍。 */\n  _setFileTextChars(relPath, chars) {\n    const prev = this._fileTextChars.get(relPath) || 0\n    if (chars > 0) this._fileTextChars.set(relPath, chars)\n    else this._fileTextChars.delete(relPath)\n    this._textChars += chars - prev\n  }\n\n  /**\n   * 绑定只对“还能续做”的任务有意义：任务已删除或已归档时清掉对应会话绑定。\n   * 否则 binding.json 会永久留着指向归档任务的条目，下一次 todo 写入又会建新任务。\n   * 只标脏、不立刻落盘——读路径不应为了清理额外写一次盘。\n   */\n  _pruneBindings() {\n    // 旧 store/手工损坏的 JSON 可能不是期望形状；读路径不能因此抛错。\n    const tasks = Array.isArray(this.tasks) ? this.tasks : []\n    const binding = this.binding\n    if (!binding || typeof binding !== 'object' || Array.isArray(binding)) return\n    const byId = new Map(tasks.filter((t) => t && t.id).map((t) => [t.id, t]))\n    let changed = false\n    for (const sid of Object.keys(binding)) {\n      const task = byId.get(binding[sid])\n      if (task && !task.archived) continue\n      delete binding[sid]\n      this._deletedBindings.add(sid)\n      changed = true\n    }\n    if (changed) {\n      this._dirtyBinding = true\n      this._auxVersion++\n    }\n  }\n\n  _loadSharded() {\n    let shardNames = []\n    try {\n      shardNames = readdirSync(path.join(this.dir, SHARDS_DIR)).filter((n) => n.endsWith('.json'))\n    } catch {\n      shardNames = []\n    }\n    for (const name of shardNames) {\n      const counter = { chars: 0 }\n      const shard = loadJson(path.join(this.dir, SHARDS_DIR, name), null, counter)\n      if (!shard || typeof shard.relPath !== 'string' || !isRecord(shard.record)) continue\n      this._setFileTextChars(shard.relPath, counter.chars)\n      this.files[shard.relPath] = shard.record\n      this._baseFileSha.set(shard.relPath, shard.record.sha256 ?? null)\n      // 畸形 shard（entries 被写成对象/null）不能让 allEntries() 在 `for…of` 上抛错，\n      // 否则一个坏文件会拖垮整个进程的每一次读取。\n      const list = Array.isArray(shard.entries) ? shard.entries.filter(isRecord) : []\n      // 老分片带着派生字段：内存里立刻剥掉，并排队等 save() 把磁盘上也压实。\n      if (list.some((e) => PERSISTED_DERIVED.some((k) => k in e))) this._compactQueue.add(shard.relPath)\n      this.entries[shard.relPath] = list.map(stripPersistedDerived)\n    }\n    this._entriesVersion++\n    this.experience = this._loadJson(path.join(this.dir, EXPERIENCE_FILE), [])\n    this.tasks = this._loadJson(path.join(this.dir, TASKS_FILE), [])\n    this.binding = this._loadJson(path.join(this.dir, BINDING_FILE), {})\n    this.watchlist = this._loadJson(path.join(this.dir, WATCH_FILE), [])\n    // 这四个集合的内容刚刚被换掉，让 auxCharsOf/精确估算重算（而不是沿用上一份实例的账）。\n    this._auxVersion++\n    this._formatWritten = existsSafe(path.join(this.dir, FORMAT_FILE))\n  }\n\n  /**\n   * 清掉 ≤0.5.10 留下的 `type-cache/` 目录。\n   *\n   * 它按内容哈希缓存 TS 增强结果，但三个增强入口（lazy 的 `fs/observed`、watch 轮询、\n   * `index_repo`）**都只在\"文件已变更并重新索引\"之后**才触发，此时内容哈希必然是新值——\n   * 这个缓存永远命中不了。实测本仓库残留 9827 个文件（`du` 41MB，内容其实 9.2MB，约 31MB\n   * 是 4KB 块开销）。这里做一次自愈清理；删的是纯缓存，不丢任何事实。\n   */\n  _removeLegacyTypeCache() {\n    const dir = path.join(this.dir, LEGACY_TYPE_CACHE_DIR)\n    if (!existsSafe(dir)) return\n    try {\n      rmSync(dir, { recursive: true, force: true })\n    } catch {\n      // 权限/占用导致删不掉也不影响 store 本身\n    }\n  }\n\n  // ---- v0.5 insights：project 级 insight 文档（任务级在 task.insights[]） ----\n  // 统一语义（本版起）：insight 是**唯一**的记忆实体，`kind:'experience'` 就是 v0.4 的经验笔记。\n  // 旧版 store 的兼容策略：把 experience.json 的内容**导入** insights.json 一次，随后把旧文件改名成\n  // `experience.json.migrated` 只读归档——不删（升级后想人工比对还有原文），但不再读写它。\n  //\n  // 归档那一步必须与\"导入\"分开判：0.5.x/0.6.x 用户的 store 里 `migratedAt` 早就写上了（那时导入的是\n  // 影子副本），可旧文件还留在磁盘上。只看 migratedAt 的话，老用户永远收不走它，\n  // `store.experience` 也永远留着第二份内容——正是\"散\"的来源。\n  _loadInsights() {\n    const doc = this._loadJson(path.join(this.dir, INSIGHTS_FILE), null)\n    this.insights = isRecord(doc) && Array.isArray(doc.items)\n      // items 里混进 null/非对象（手改或旧版写入）会让迁移与召回逐个 `.title` 抛错——过滤掉。\n      ? { ...doc, items: doc.items.filter(isRecord) }\n      : { version: 1, migratedAt: null, items: [] }\n    this._migrateExperienceToInsights()\n    // PR3：v1 → v2 懒回填派生 trigger（纯确定性、幂等；不调用模型，不改写已有字段）\n    if (backfillDerivedTriggers(this.insights)) this._dirtyInsights = true\n    // 迁移与回填都会改 items；换掉整个文档后让 auxCharsOf/精确估算重算。\n    this._baseInsightIds = new Set(this.insights.items.map((it) => it?.id).filter(Boolean))\n    this._auxVersion++\n  }\n\n  _migrateExperienceToInsights() {\n    const legacyFile = path.join(this.dir, EXPERIENCE_FILE)\n    const legacyOnDisk = existsSafe(legacyFile)\n    const legacy = Array.isArray(this.experience) ? this.experience : []\n    if (legacyOnDisk && !Array.isArray(this.experience)) {\n      console.error(`[dsh-project-memory] ${EXPERIENCE_FILE} is not an array; importing nothing (file kept as-is)`)\n      return\n    }\n    let imported = 0\n    // 导入 + 落盘这条支路必须有\"值得写\"的输入才走：`migratedAt` 为空 + 旧文件不在 + 内存里也没有\n    // 旧条目（全新根）时直接跳过。否则 `load()` 会在一个从没被索引过的空目录里 mkdir + 写\n    // insights.json —— 那会让 `audit.js` 的 auditDirReady（\"目录已存在\"）与 auto-inject 的\n    // `if (store.hasContent) store.save()` 双双失效，容器目录被当成项目根（issue #5 同类）。\n    // 归档旧文件是**另一支**（下面单独判 legacyOnDisk），所以跳过这里不影响真升级。\n    if (!this.insights.migratedAt && (legacyOnDisk || legacy.length > 0)) {\n      const now = new Date().toISOString()\n      const known = new Set(this.insights.items.map((it) => it.id))\n      for (const item of legacy) {\n        if (!item || !item.problem || known.has(item.id)) continue\n        known.add(item.id)\n        this.insights.items.push({\n          id: item.id,\n          kind: 'experience',\n          scope: 'project',\n          title: String(item.problem).slice(0, 120),\n          problem: item.problem,\n          solution: item.solution,\n          files: item.sourceFile ? [item.sourceFile] : [],\n          symbols: [],\n          sourceTaskIds: [],\n          source: 'migrate',\n          confidence: 1,\n          hitCount: 0,\n          createdAt: item.createdAt || now,\n          updatedAt: item.updatedAt || now,\n        })\n        imported++\n      }\n      this.insights.migratedAt = now\n      try {\n        mkdirSync(this.dir, { recursive: true })\n        writeJsonAtomic(path.join(this.dir, INSIGHTS_FILE), this.insights, { ensureDir: false })\n      } catch (err) {\n        // 没写进 insights.json 就**不能**把旧文件收走：那会真的丢数据。\n        console.error(`[dsh-project-memory] insights migration write failed, keeping ${EXPERIENCE_FILE}: ${err.message}`)\n        return\n      }\n    }\n    if (legacyOnDisk) {\n      try {\n        renameSync(legacyFile, `${legacyFile}.migrated`)\n      } catch (err) {\n        console.error(`[dsh-project-memory] could not archive ${EXPERIENCE_FILE} (imported ${imported} note(s)): ${err.message}`)\n      }\n    }\n    this.experience = []\n  }\n\n  insightsDoc() {\n    return this.insights\n  }\n\n  insightItems() {\n    return this.insights.items\n  }\n\n  replaceInsightItems(items) {\n    const next = new Set((items || []).map((it) => it?.id).filter(Boolean))\n    // 与上次落盘的基线比，而不是与当前数组比：调用方经常先原地 splice 再调用这里。\n    for (const id of this._baseInsightIds) if (!next.has(id)) this._deletedInsightIds.add(id)\n    for (const id of next) {\n      this._deletedInsightIds.delete(id)\n      if (!this._baseInsightIds.has(id)) this._createdInsightIds.add(id)\n    }\n    this.insights.items = items\n    this._baseInsightIds = next\n    this._dirtyInsights = true\n    this._auxVersion++\n  }\n\n  /**\n   * 调用方**直接改过** task 内容（包括 task 内的条目）后的标脏入口。任务树不在 `addTask` /\n   * `updateTask` 那几条写口里，所以这里也要 bump 内容版本，否则精确估算停在前一水位。\n   */\n  markTasksDirty() {\n    this._dirtyTasks = true\n    this._auxVersion++\n  }\n\n  cleanStaleTmp({ force = false } = {}) {\n    // store 根目录只有几个文件，每次 save 扫一遍很便宜（崩溃遗留的 aux `.tmp` 立刻收走）。\n    // `shards/` 才是 O(N)：12k 分片时每次单文件更新都 readdir 一遍，在 NTFS 上是实打实的卡顿。\n    // 分片里的 .tmp 只影响体积、不影响正确性，60s 扫一次足够；`force` 给测试/诊断用。\n    const now = Date.now()\n    const scanDirs = [this.dir]\n    if (force || now - this._lastShardTmpSweep >= 60_000) {\n      this._lastShardTmpSweep = now\n      scanDirs.push(path.join(this.dir, SHARDS_DIR))\n    }\n    for (const dir of scanDirs) {\n      let entries\n      try {\n        entries = readdirSync(dir)\n      } catch {\n        continue\n      }\n      for (const name of entries) {\n        if (!name.endsWith('.tmp')) continue\n        try {\n          if (now - statSync(path.join(dir, name)).mtimeMs > 60000) unlinkSync(path.join(dir, name))\n        } catch {\n          // already gone or locked; skip\n        }\n      }\n    }\n  }\n\n  /**\n   * store 目录**自我忽略**：在目录里放一个内容为 `*` 的 `.gitignore`。\n   *\n   * 为什么不写进用户的 `.gitignore`：那是用户的文件，插件不该改；而且\"忘了加\"的代价\n   * 是一次误提交。为什么这样就够：git 会读取工作区里**任意**目录下的 `.gitignore`，\n   * 而 `*` 连这个 `.gitignore` 自己一起命中，于是 `git status` / `git add -A` 里整棵树\n   * 都不出现，用户一个字都不用写（`git check-ignore -v` 可复核）。\n   *\n   * 顺带的好处：被忽略的文件不会被 `git clean -fd` 删除（未跟踪且未忽略的会被删）。\n   * 想把记忆跟着仓库提交：`git add -f .dsh-project-memory`——已跟踪的文件不受忽略规则影响。\n   */\n  ensureSelfIgnore() {\n    if (this._selfIgnoreReady) return\n    if (!existsSafe(this.dir)) return\n    const file = path.join(this.dir, GITIGNORE_FILE)\n    if (existsSafe(file)) {\n      this._selfIgnoreReady = true\n      return\n    }\n    try {\n      writeFileSync(file, '# dsh-project-memory: local by default. `git add -f` to commit it.\\n*\\n')\n      this._selfIgnoreReady = true\n    } catch {\n      // 旁路：写不进去不影响存储本身\n    }\n  }\n\n  /** 是否有待落盘的变更；逐出缓存前用它避免为干净 store 触发 save 的旁路副作用。 */\n  hasDirty() {\n    return this._compactQueue.size > 0\n      || this._dirtyShards.size > 0\n      || this._removedShards.size > 0\n      || this._dirtyInsights\n      || this._dirtyTasks\n      || this._dirtyBinding\n      || this._dirtyWatch\n  }\n\n  /**\n   * @param {{ timeoutMs?: number }} [options] 等锁上限。默认 15s：写路径的正确性靠**同步等待**，\n   *   不靠后台重试——用户结束对话就会关 dsh，不会等重试。重试只是长驻进程的兜底。\n   * @returns {boolean} 是否真的落盘（无脏数据也算成功）\n   */\n  save(options = {}) {\n    // 没有脏数据就不落盘。watch 每轮对每个根都无条件 commit → save；照旧执行的话，\n    // 末尾的 ID 缓存失效会打在跨实例共享的 store 上，等于每轮清空一次 IDF 复用（v0.3.4 的 20x）。\n    // 待压实队列不算\"脏数据\"，但它需要有界推进，所以也走这条落盘路径。\n    const compacting = this._compactQueue.size > 0\n    const dirty =\n      compacting ||\n      this._dirtyShards.size > 0 ||\n      this._removedShards.size > 0 ||\n      this._dirtyInsights ||\n      this._dirtyTasks ||\n      this._dirtyBinding ||\n      this._dirtyWatch ||\n      !this._formatWritten\n    if (dirty && !this._storeDirReady) {\n      mkdirSync(this.dir, { recursive: true })\n      this._storeDirReady = true\n    }\n    // 崩溃遗留的 *.tmp 无论有没有脏数据都顺手清掉（两次 readdir，自带 try/catch）\n    this.cleanStaleTmp()\n    // 自我忽略也在无脏数据时执行：老版本建出来的 store 会在下一次 save 时补上。\n    this.ensureSelfIgnore()\n    if (!dirty) {\n      this.lastSaveOk = true\n      untrackDirty(this)\n      return true\n    }\n    // 跨进程：整段读改写放进目录锁。默认同步等待 15s——写路径的正确性靠\"等到锁\"，\n    // 不靠后台重试（用户结束对话就关 dsh）。真拿不到时保持脏状态并登记退出 flush；\n    // 默认静默，不向用户/模型抛提示。\n    const timeoutMs = Number.isFinite(options.timeoutMs) ? options.timeoutMs : 15000\n    const release = acquireDirLock(this.dir, { timeoutMs, ensureDir: false })\n    if (!release) {\n      this.lastSaveOk = false\n      trackDirty(this)\n      if (!this._lockWarned) {\n        this._lockWarned = true\n        debugPersistence(`[dsh-project-memory] store ${this.dir} is busy (another dsh process is writing); this write is pending.`)\n      }\n      this._scheduleSaveRetry()\n      return false\n    }\n    let wroteInsights = false\n    let wroteTasks = false\n    try {\n      // 先合并另一进程已落盘的小文档，再写；分片按“加载时 hash”做冲突检测。\n      this._mergeAuxFromDisk()\n      if (!this._formatWritten) {\n        writeJsonAtomic(path.join(this.dir, FORMAT_FILE), { version: 2, layout: 'sharded' }, { ensureDir: false })\n        this._formatWritten = true\n      }\n      // 存量压实：≤0.5.10 的分片带着派生字段，而那些字段只在分片被重写时才会从磁盘消失。\n      // 每轮最多补写 COMPACT_BATCH 个，让升级后的 store 在后续任意一次 save（watch 轮询、\n      // 索引、写入）里自动收敛，而不是永远停在旧体积。\n      let compactBudget = COMPACT_BATCH\n      for (const rel of this._compactQueue) {\n        if (compactBudget <= 0) break\n        compactBudget--\n        this._compactQueue.delete(rel)\n        if (this.files[rel]) this._dirtyShards.add(rel)\n      }\n      for (const rel of this._dirtyShards) {\n        if (this.files[rel]) {\n          const nextSha = this.files[rel].sha256 ?? null\n          const base = this._baseFileSha.get(rel) ?? null\n          const disk = this._shardDiskRecord(rel)\n          // 磁盘分片在加载后被别的进程改过，且不是我们这一版：按 indexedAt 收敛，\n          // 本地更新则覆盖（否则显式 index 的结果会静默丢掉），对方更新则把对方读回内存。\n          if (disk.exists && disk.sha !== base && disk.sha !== nextSha) {\n            const localAt = Date.parse(this.files[rel].indexedAt || '') || 0\n            const diskAt = Date.parse(disk.record?.indexedAt || '') || 0\n            if (localAt > diskAt) {\n              this._ensureShardsDir()\n              writeJsonAtomic(shardRelPath(this.dir, rel), { relPath: rel, record: this.files[rel], entries: (this.entries[rel] || []).map(withoutPersistedDerived) }, { ensureDir: false })\n              this._baseFileSha.set(rel, nextSha)\n              continue\n            }\n            this._adoptDiskShard(rel, disk)\n            this._warnConflict(rel)\n            continue\n          }\n          this._ensureShardsDir()\n          writeJsonAtomic(shardRelPath(this.dir, rel), { relPath: rel, record: this.files[rel], entries: (this.entries[rel] || []).map(withoutPersistedDerived) }, { ensureDir: false })\n          this._baseFileSha.set(rel, nextSha)\n        } else {\n          this._removedShards.add(rel)\n        }\n      }\n      this._dirtyShards.clear()\n      for (const rel of this._removedShards) {\n        const base = this._baseFileSha.get(rel) ?? null\n        const disk = this._shardDiskRecord(rel)\n        if (disk.exists && disk.sha !== base) {\n          // 删除与另一进程的更新撞车：没有删除时间戳可比，保守采用对方版本，\n          // 至少让内存与磁盘一致（旧实现只跳过写，内存仍认为已删）。\n          this._adoptDiskShard(rel, disk)\n          this._warnConflict(rel)\n          continue\n        }\n        try {\n          unlinkSync(shardRelPath(this.dir, rel))\n        } catch {\n          // shard file already gone; nothing to do\n        }\n        this._baseFileSha.delete(rel)\n      }\n      this._removedShards.clear()\n      wroteInsights = this._dirtyInsights\n      wroteTasks = this._dirtyTasks\n      if (wroteInsights) {\n        // v2 → v3 是纯语义升级（`kind:'experience'` 从\"影子副本\"变成一等实体），形状不变；\n        // 落盘即把版本推上去，老版本读到 v3 也照样按 v2 的字段解析（它只是排除 experience 影子）。\n        if (this.insights && this.insights.version !== 3) this.insights.version = 3\n        writeJsonAtomic(path.join(this.dir, INSIGHTS_FILE), this.insights, { ensureDir: false })\n        this._dirtyInsights = false\n      }\n      if (this._dirtyTasks) {\n        writeJsonAtomic(path.join(this.dir, TASKS_FILE), this.tasks, { ensureDir: false })\n        this._dirtyTasks = false\n      }\n      if (this._dirtyBinding) {\n        writeJsonAtomic(path.join(this.dir, BINDING_FILE), this.binding, { ensureDir: false })\n        this._dirtyBinding = false\n      }\n      if (this._dirtyWatch) {\n        writeJsonAtomic(path.join(this.dir, WATCH_FILE), this.watchlist, { ensureDir: false })\n        this._dirtyWatch = false\n      }\n    } finally {\n      release()\n    }\n    this._saveRetryAttempts = 0\n    this.lastSaveOk = true\n    untrackDirty(this)\n    // 落盘成功才推进基线：失败时保持\"本进程新建\"的标记，下一次 save 仍要补写。\n    if (wroteInsights) {\n      this._baseInsightIds = new Set(this.insights.items.map((it) => it?.id).filter(Boolean))\n      this._createdInsightIds.clear()\n    }\n    if (wroteTasks) this._createdTaskIds.clear()\n    return true\n  }\n\n  /**\n   * 冲突时采用另一进程的分片：内存里的 record/entries 与磁盘对齐，并让 IDF/驻留账失效。\n   * 磁盘 entries 可能来自旧版本或损坏文件，和 `_loadSharded` 一样只收 record。\n   */\n  _adoptDiskShard(rel, disk) {\n    const entries = (disk.entries || []).filter(isRecord).map(stripPersistedDerived)\n    this.files[rel] = disk.record\n    this.entries[rel] = entries\n    this._setFileTextChars(rel, entryTextChars(entries))\n    this._entriesVersion++\n    this._baseFileSha.set(rel, disk.sha)\n  }\n\n  /** 读磁盘分片（不存在/损坏都返回 exists:false）。 */\n  _shardDiskRecord(rel) {\n    try {\n      const doc = JSON.parse(readFileSync(shardRelPath(this.dir, rel), 'utf8'))\n      if (!isRecord(doc) || typeof doc.relPath !== 'string' || !isRecord(doc.record)) {\n        return { exists: false, sha: null, record: null, entries: [] }\n      }\n      return {\n        exists: true,\n        sha: doc.record.sha256 ?? null,\n        record: doc.record,\n        entries: Array.isArray(doc.entries) ? doc.entries : [],\n      }\n    } catch {\n      return { exists: false, sha: null, record: null, entries: [] }\n    }\n  }\n\n  /** 首次写分片前建一次 shards/；之后每次 save 都省掉一次 mkdir。 */\n  _ensureShardsDir() {\n    if (this._shardsDirReady) return\n    mkdirSync(path.join(this.dir, SHARDS_DIR), { recursive: true })\n    this._shardsDirReady = true\n  }\n\n  /** 退出/卸载路径的同步兜底（见 util/flush.js）。 */\n  flushPending(timeoutMs = 1500) {\n    return this.save({ timeoutMs })\n  }\n\n  /** 锁竞争后的有限次延迟重试；失败仍保持脏状态，下一次写继续尝试。 */\n  _scheduleSaveRetry() {\n    // 旧实现 3 次 × ~2s ≈ 8.3s，**永远小于** staleMs=10s：一个刚崩溃的跨机锁会让所有重试落空。\n    // 同机崩溃锁现在由 pid 判活立即回收（见 util/fs.js），这里的预算只兜跨机 stale 锁。\n    const delays = [100, 500, 2000, 6000, 12000]\n    if (this._saveRetryTimer || this._saveRetryAttempts >= delays.length) return\n    const delay = delays[this._saveRetryAttempts++]\n    this._saveRetryTimer = setTimeout(() => {\n      this._saveRetryTimer = null\n      try {\n        this.save({ timeoutMs: 2000 })\n      } catch (err) {\n        console.error(`[dsh-project-memory] deferred save failed: ${err?.message || err}`)\n      }\n    }, delay)\n    this._saveRetryTimer.unref?.()\n  }\n\n  /** 冲突只提示一次：这是“对方更新更晚”的正常并发结果，不是每轮刷屏的故障。 */\n  _warnConflict(rel) {\n    if (this._conflictWarned.has(rel)) return\n    this._conflictWarned.add(rel)\n    console.error(`[dsh-project-memory] ${rel} changed by another dsh process; this local copy was not written (it will be re-derived on the next scan).`)\n  }\n\n  /**\n   * 写盘前把另一进程已落盘的小文档合并进来。\n   *\n   * 只合并不覆盖：同 id 取 `updatedAt` 更新的一侧；本进程删掉的 id 用墓碑挡住，\n   * 避免“删了又被对方的旧副本复活”。分片不走这里（按 hash 冲突检测）。\n   */\n  _mergeAuxFromDisk() {\n    if (this._dirtyInsights) {\n      // 先按“上次落盘基线”记墓碑：prune/applyDecay 等原地 splice 不经过 replaceInsightItems。\n      const current = new Set(this.insights.items.map((it) => it?.id).filter(Boolean))\n      for (const id of this._baseInsightIds) if (!current.has(id)) this._deletedInsightIds.add(id)\n      for (const id of current) this._deletedInsightIds.delete(id)\n      const disk = this._loadJson(path.join(this.dir, INSIGHTS_FILE), null)\n      if (isRecord(disk) && Array.isArray(disk.items)) {\n        const byId = new Map()\n        for (const it of disk.items) if (isRecord(it) && it.id) byId.set(it.id, it)\n        for (const it of this.insights.items) {\n          if (!isRecord(it) || !it.id) continue\n          if (this._deletedInsightIds.has(it.id)) {\n            byId.delete(it.id)\n            continue\n          }\n          const prev = byId.get(it.id)\n          if (!prev) {\n            // 磁盘没有：本进程新建的才补写；否则是**对方删了**，丢掉内存里的旧副本。\n            if (this._createdInsightIds.has(it.id)) byId.set(it.id, it)\n            continue\n          }\n          if (newerIso(it.updatedAt, prev.updatedAt) >= 0) byId.set(it.id, it)\n        }\n        for (const id of this._deletedInsightIds) byId.delete(id)\n        this.insights = { ...this.insights, items: [...byId.values()] }\n        this._baseInsightIds = new Set(this.insights.items.map((it) => it?.id).filter(Boolean))\n        this._auxVersion++\n      }\n    }\n    if (this._dirtyTasks) {\n      const disk = this._loadJson(path.join(this.dir, TASKS_FILE), [])\n      if (Array.isArray(disk)) {\n        const byId = new Map()\n        for (const t of disk) if (isRecord(t) && t.id) byId.set(t.id, t)\n        for (const t of this.tasks) {\n          if (!isRecord(t) || !t.id || this._deletedTaskIds.has(t.id)) {\n            if (isRecord(t) && t.id) byId.delete(t.id)\n            continue\n          }\n          const prev = byId.get(t.id)\n          if (!prev) {\n            // 同 insights：磁盘缺失 = 对方删了，只有本进程新建的任务才补写。\n            if (this._createdTaskIds.has(t.id)) byId.set(t.id, t)\n            continue\n          }\n          if (newerIso(t.updatedAt || t.lastActiveAt, prev.updatedAt || prev.lastActiveAt) >= 0) byId.set(t.id, t)\n        }\n        // 本地删除必须从磁盘副本里剔除：`removeTask` 已把它从内存数组移除，上面的循环\n        // 根本看不到它；少了这一行，删任务会在**同一次 save 里**被另一份磁盘快照写回来。\n        for (const id of this._deletedTaskIds) byId.delete(id)\n        this.tasks = [...byId.values()]\n        this._auxVersion++\n      }\n    }\n    if (this._dirtyBinding) {\n      const disk = this._loadJson(path.join(this.dir, BINDING_FILE), {})\n      if (isRecord(disk)) {\n        const merged = { ...disk }\n        for (const [sid, tid] of Object.entries(this.binding)) merged[sid] = tid\n        for (const sid of this._deletedBindings) delete merged[sid]\n        this.binding = merged\n        this._auxVersion++\n      }\n    }\n    if (this._dirtyWatch) {\n      const disk = this._loadJson(path.join(this.dir, WATCH_FILE), [])\n      if (Array.isArray(disk)) {\n        const set = new Set([...disk, ...this.watchlist])\n        for (const root of this._removedWatch) set.delete(root)\n        this.watchlist = [...set]\n        this._auxVersion++\n      }\n    }\n  }\n\n  getIdfCache() {\n    // IDF 只依赖 entries（title/keywords/summary），所以按 entries 的变更计数失效：\n    // 只写经验/insight 或只做存量压实的 save 不会再无谓地重建 IDF。\n    if (this._idfCache && this._idfCache.version === this._entriesVersion) {\n      return this._idfCache.idf\n    }\n    const idf = this._rebuildIdf()\n    this._idfCache = { version: this._entriesVersion, idf }\n    return idf\n  }\n\n  _rebuildIdf() {\n    const entries = this.allEntries()\n    const N = entries.length\n    if (N === 0) return {}\n    const df = {}\n    for (const entry of entries) {\n      // 语料必须与**检索**同源：检索走 search.js 的 weightedFieldText = title×5 + keywords\n      // + summary + **terms** + sourcePath。此前这里手抄了一份少了 `terms`/`sourcePath` 的\n      // 副本，于是只出现在 `terms` 里的词 df=0 → 被当成极稀有词拿虚高 IDF（而 `terms` 正是\n      // 0.5.x 为修\"只有前 300 字符可检索\"加的主检索面）。直接调 makeSearchText，权重自动对齐。\n      const terms = tokenizeRaw(makeSearchText(entry))\n      const seen = new Set(terms)\n      for (const t of seen) {\n        df[t] = (df[t] || 0) + 1\n      }\n    }\n    const idf = {}\n    for (const [t, df_t] of Object.entries(df)) {\n      idf[t] = Math.log(1 + (N - df_t + 0.5) / (df_t + 0.5))\n    }\n    return idf\n  }\n\n  addWatch(root) {\n    if (!this.watchlist.includes(root)) {\n      this.watchlist.push(root)\n      this